(window.TNQ=window.TNQ||[]).push({"terms":{"조연성 가스":{"d":"스스로 타지는 않지만 가연물의 연소를 돕는 산소 같은 가스입니다.","r":[]},"인화점":{"d":"점화원을 가까이 댔을 때 불이 붙을 수 있는 가연물의 가장 낮은 온도입니다.","r":["연소점","발화점"]},"연소점":{"d":"점화원을 제거해도 연소가 계속 이어지는 가장 낮은 온도입니다.","r":["인화점","발화점"]},"발화점":{"d":"점화원 없이도 스스로 불이 붙는 가장 낮은 온도입니다.","r":["인화점","연소점"]},"연소범위":{"d":"불이 붙을 수 있는 가연성 가스의 농도 범위로 하한계와 상한계로 나뉩니다.","r":["위험도"]},"위험도":{"d":"연소범위의 폭을 하한계로 나눈 값으로 클수록 위험하다고 봅니다.","r":["연소범위"]},"르샤틀리에":{"d":"혼합가스의 연소 한계를 성분별 농도와 한계값으로 구하는 식의 이름입니다.","r":["연소범위"]},"이론공기량":{"d":"가연물을 완전연소시키는 데 이론상 필요한 최소 공기량입니다.","r":["과잉공기량","공기비"]},"과잉공기량":{"d":"실제로 쓴 공기량에서 이론공기량을 뺀 양입니다.","r":["이론공기량","공기비"]},"공기비":{"d":"실제공기량을 이론공기량으로 나눈 값입니다.","r":["이론공기량","과잉공기량"]},"분무연소":{"d":"액체 연료를 미세한 방울로 만들어 태우는 연소입니다.","r":[]},"역화":{"d":"연소속도가 분출속도보다 커서 불꽃이 버너 안으로 들어가는 현상입니다.","r":[]},"활성화에너지":{"d":"반응이 시작되기 위해 넘어야 하는 에너지 장벽으로 클수록 반응이 느립니다.","r":[]},"감광계수":{"d":"빛이 연기를 통과하며 줄어드는 정도로 연기의 농도를 나타내는 지표입니다.","r":[]},"굴뚝효과":{"d":"건물 안팎 온도차로 공기가 수직으로 흐르며 연기가 위로 퍼지는 현상입니다.","r":["중성대"]},"중성대":{"d":"건물 안팎의 압력이 같아지는 높이로 그 위아래에서 공기 흐름 방향이 바뀝니다.","r":["굴뚝효과"]},"폭굉":{"d":"충격파를 동반해 음속보다 빠르게 전파하는 폭발적 연소입니다.","r":[]},"분진폭발":{"d":"공기 중에 떠 있는 가연성 고체의 미세한 가루가 착화되어 터지는 폭발입니다.","r":[]},"증기운폭발":{"d":"대량의 가연성 증기가 열린 곳에서 구름처럼 퍼졌다가 착화되어 터지는 폭발입니다.","r":[]},"화재하중":{"d":"단위 면적당 가연물이 낼 수 있는 발열량을 목재 무게로 환산한 값입니다.","r":[]},"환기계수":{"d":"개구부 면적과 개구부 높이의 제곱근을 곱한 값으로 구획실 연소를 좌우합니다.","r":["환기지배형"]},"환기지배형":{"d":"개구부가 작아 공기 공급이 연소를 제한하는 구획실 화재입니다.","r":["연료지배형"]},"연료지배형":{"d":"개구부가 충분해 가연물의 양이 연소를 좌우하는 구획실 화재입니다.","r":["환기지배형"]},"훈소":{"d":"불꽃 없이 표면에서 천천히 타는 연소입니다.","r":[]},"플래시오버":{"d":"구획실 전체가 순식간에 화염에 휩싸이는 급격한 화재 확대 현상입니다.","r":[]},"파이어볼":{"d":"분출한 증기가 착화되어 공 모양으로 타오르는 큰 화염 덩어리입니다.","r":[]},"내화구조":{"d":"화재에 견디는 성능을 가진 구조로 국토교통부령 기준에 맞는 구조입니다.","r":["주요구조부"]},"불연재료":{"d":"불에 타지 않는 성질을 가진 재료입니다.","r":["난연재료","준불연재료"]},"난연재료":{"d":"불에 잘 타지 않는 성능을 가진 재료입니다.","r":["불연재료","준불연재료"]},"준불연재료":{"d":"불연재료에 준하는 성질을 가진 재료입니다.","r":["불연재료","난연재료"]},"주요구조부":{"d":"내력벽, 기둥, 바닥, 보, 지붕틀, 주계단처럼 건물을 지탱하는 구조 부분입니다.","r":["내화구조"]},"방화구획":{"d":"불과 연기가 번지지 않도록 내화구조 벽과 방화문 등으로 나눈 구획입니다.","r":["자동방화셔터"]},"자동방화셔터":{"d":"연기나 열을 감지해 방화구획을 자동으로 닫는 셔터입니다.","r":["방화구획"]},"직통계단":{"d":"어느 층에서 피난층이나 지상까지 곧바로 이어지는 계단입니다.","r":["피난계단","특별피난계단"]},"피난계단":{"d":"화재 때 피난을 위해 내화구조로 구획해 설치하는 계단입니다.","r":["직통계단","특별피난계단"]},"특별피난계단":{"d":"노대나 부속실을 거쳐 연기가 들어오지 않게 만든 더 안전한 피난계단입니다.","r":["피난계단","직통계단"]},"피난안전구역":{"d":"고층건물에서 화재 때 잠시 대피할 수 있게 마련한 안전한 층입니다.","r":[]},"대피공간":{"d":"아파트 발코니 등에 두어 화재 때 세대 안에서 머물 수 있는 방화구획 공간입니다.","r":[]},"페일 세이프":{"d":"한 가지 수단이 실패해도 다른 수단이 작동하도록 해 두는 안전 원칙입니다.","r":["풀 프루프"]},"풀 프루프":{"d":"사람이 잘못 조작해도 위험하지 않게 만드는 안전 원칙입니다.","r":["페일 세이프"]},"조닝":{"d":"피난로를 안전성이 높아지는 구역으로 나누어 계획하는 방법입니다.","r":[]},"방화문":{"d":"연기나 불꽃을 막도록 항상 닫혀 있거나 자동으로 닫히는 문입니다.","r":["방화구획"]},"스모크타워":{"d":"굴뚝 같은 수직 통로의 부력으로 연기를 밖으로 빼는 제연 방식입니다.","r":[]},"가압":{"d":"출입문과 벽 사이의 압력차로 연기가 들어오지 못하게 막는 제연 방식입니다.","r":[]}},"notes":{"(1,000×10,500 + 2,000×7,500) / (4,500×(10×5)) = 25,500,000 / 225,000 = 113.33 kg/m²":"발열량 합 25,500,000 kcal를 4,500과 바닥면적의 곱 225,000으로 나누면 113.33 kg/m²입니다.","100 K → 300 K 이면 (300/100)⁴ = 81배":"절대온도가 100 K에서 300 K로 높아지면 비의 네제곱만큼인 81배가 됩니다.","100 g/m²·s × 50 kJ/g × π(1 m)² = 15,708 kW ≈ 15,700 kW":"100 g/m²·s에 50 kJ/g과 풀 면적 π(1 m)²을 곱하면 약 15,700 kW입니다.","11층(공동주택 16층) 이상인 층 또는 지하 3층 이하인 층(바닥면적 400 m² 미만인 층 제외)으로부터의 직통계단은 특별피난계단, 갓복도식 공동주택은 제외":"11층(공동주택 16층) 이상이나 지하 3층 이하 층으로부터의 직통계단은 특별피난계단이며 갓복도식 공동주택은 제외합니다.","1층과 2층의 일부를 동일한 용도로 사용하고 다른 부분과 구획된 부분(바닥면적 합계 500 m² 이하)":"1층과 2층 일부를 같은 용도로 쓰고 다른 부분과 구획된 부분은 바닥면적 합계 500 m² 이하일 때 완화됩니다.","200,000 kW, R = 25 m → Q/(4πR²) = 25.46 kW/m²":"열방출 200,000 kW를 반지름 25 m 구의 표면적으로 나누면 25.46 kW/m²입니다.","2021-25: 20 g/m²·s × 0.004 g/g ×":"질량연소유속 20 g/m²·s에 수율 0.004 g/g을 곱하는 과정입니다.","2023-1: 메테인 20, 부탄 30, 프로판 50 vol% (하한 5.0, 1.8, 2.1) → 100 / (4 + 16.67 + 23.81) = 2.25 vol%":"메테인 20, 부탄 30, 프로판 50 vol% 혼합의 하한계는 성분별 비를 합해 100에서 나눈 2.25 vol%입니다.","2023-22: 2 MW ÷ 약 2.594 kJ/g(비열 4.18, 20→100℃, 증발잠열 2,260 가정과 일치) = 약 770.9 g/s":"열방출 2 MW를 물이 흡수하는 약 2.594 kJ/g으로 나누면 약 770.9 g/s가 됩니다.","2025-20: CH4 70, C2H6 20, C3H8 10 vol% (하한 5.0, 3.0, 2.1) → 100 / (14 + 6.67 + 4.76) = 3.93 vol%":"CH4 70, C2H6 20, C3H8 10 vol% 혼합의 하한계는 같은 방식으로 계산한 3.93 vol%입니다.","2NaHCO3 → Na2CO3 + H2O + CO2, NaHCO3 84 g = 1 mol → CO2 0.5 mol, 1 atm, 270℃(543 K)에서 V = nRT/P = 0.5×0.082×543 = 22.3 L":"탄산수소나트륨 84 g은 1 mol이고 분해해서 나온 이산화탄소 0.5 mol은 270℃에서 22.3 L입니다.","2 m² = 0.16 g/s (면적 2 m²는 정답에서 역산)":"면적 2 m²는 정답에서 역산한 값이며 곱하면 0.16 g/s가 됩니다.","2층 이상 11층 이하인 층에 각각 1개소 이상, 직접 지상으로 통하는 출입구가 있는 층과 바닥구조체 윗면 높이가 지표면에서 44m를 초과하는 층은 설치하지 않을 수 있다":"소방관 진입창은 2층 이상 11층 이하 층마다 1개소 이상이며 지상 출입구 층과 높이 44m를 넘는 층은 생략할 수 있습니다.","30층 이상 49층 이하 지하연계 복합건축물은 건축법 시행령 제34조제4항 피난안전구역, 16~29층은 밀도 1.5명/m² 초과 층의 사용형태별 면적 합의 1/10 면적":"지하연계 복합건축물은 층수에 따라 정한 피난안전구역을 두며 16~29층은 밀도 1.5명/m² 초과 층 면적 합의 1/10입니다.","400℃ = 673 K, ε = 0.8 → 0.8 × 5.67×10⁻⁸ × 673⁴ ≈ 9,300 W/m² (정답 9,304)":"400℃를 673 K로 바꾸고 방사율 0.8을 넣어 계산하면 복사 열유속이 약 9,300 W/m²입니다.","5층 이상 또는 지하 2층 이하인 층에 설치하는 직통계단은 피난계단 또는 특별피난계단으로 설치":"5층 이상이거나 지하 2층 이하인 층의 직통계단은 피난계단이나 특별피난계단으로 설치합니다.","5층 이상 전시장·동식물원·판매·여객용 운수·운동·위락·관광휴게(다중이용)·생활권 수련시설 층: 해당 용도 바닥면적 합계가 2,000 m²를 넘으면 넘는 2,000 m² 이내마다 1개소의 피난계단 또는 특별피난계단 추가":"5층 이상 전시장 등 층은 용도 바닥면적 합계가 2,000 m²를 넘으면 넘는 2,000 m² 이내마다 1개소씩 피난계단을 더 둡니다.","A√H (개구부 면적 × √개구부 높이)":"환기계수는 개구부 면적에 개구부 높이의 제곱근을 곱한 값입니다.","C3H8 + 5O2 → 3CO2 + 4H2O, 프로페인 5 mol이 만드는 CO2 = 15 mol = 336 L = 0.336 m³":"프로페인 5 mol이 완전연소하면 이산화탄소 15 mol, 336 L가 생깁니다.","C4H10 + 6.5O2 → 4CO2 + 5H2O, 부탄 5 mol에 필요한 O2 = 32.5 mol = 728 L = 0.728 m³":"부탄 5 mol에는 산소가 32.5 mol 필요하며 부피로 0.728 m³입니다.","CH4 5.0×2 = 10, C2H6 3.0×3.5 = 10.5, C4H10 1.8×6.5 = 11.7 vol%":"메테인 10, 에테인 10.5, 부탄 11.7 vol%로 하한계와 산소 몰수의 곱이 나옵니다.","CO의 산화(CO + OH → CO2 + H)에 결정적인 요소":"OH 라디칼은 일산화탄소를 이산화탄소로 바꾸는 산화 반응에 결정적인 요소입니다.","Gi: 가연물의 양[kg], Hi: 가연물의 단위중량당 발열량[kcal/kg], H0: 목재의 표준발열량 4,500 kcal/kg, A: 화재실의 바닥면적[m²]":"계산에는 가연물 양과 단위중량당 발열량, 목재 표준발열량 4,500 kcal/kg, 화재실 바닥면적을 씁니다.","H = (UFL − LFL) / LFL, 클수록 위험하다":"위험도는 연소범위 폭을 하한계로 나눈 값이며 클수록 위험합니다.","L = 0.235·Q̇^(2/5) − 1.02·D (Q̇ kW, D m)":"Heskestad 식은 열방출률의 5분의 2제곱에 상수를 곱하고 풀 지름 항을 빼서 평균 화염 높이를 구합니다.","L = 100 / (V1/L1 + V2/L2 + …), V는 각 가스 vol%(합 100), L은 각 가스 하한계":"르샤틀리에 식은 각 가스의 농도를 하한계로 나눈 값을 합해 100을 그 합으로 나누어 혼합 하한계를 구합니다.","MOC 크기: CH4 < C2H6 < C4H10":"최소산소농도는 메테인이 가장 작고 에테인, 부탄 순으로 커집니다.","Q = 5 kcal/min = 300 kcal/h":"분당 5 kcal는 시간당 300 kcal이므로 단위를 시간으로 맞춰 계산합니다.","Q̇ = m″·ΔHc·A (질량연소유속 × 유효연소열 × 연소면적)":"열방출률은 질량연소유속에 유효연소열과 연소면적을 곱해 구합니다.","Q̇ = α·t², 약 1 MW(1,055 kW)에 도달하는 시간으로 구분":"화재성장속도는 열방출률이 시간 제곱에 비례한다고 보고 약 1 MW에 이르는 시간으로 등급을 나눕니다.","R ≈ 5.5·A√H [kg/min] (카와고에)":"환기지배형 화재의 연소율은 약 5.5에 환기계수를 곱한 분당 kg이라는 카와고에 식입니다.","SO2는 황 함유 물질의 생성물":"SO2는 황을 함유한 물질이 탈 때 생기는 생성물입니다.","k = A·exp(−Ea/RT)":"아레니우스 식은 반응속도상수를 빈도계수와 지수항의 곱으로 나타내며 지수에 활성화에너지와 온도가 들어갑니다.","kcal/h → W 환산 시 1 kcal/h = 1.163 W":"kcal/h를 W로 바꿀 때는 1 kcal/h가 1.163 W에 해당함을 적용합니다.","q = Σ(Gi·Hi) / (H0·A) = ΣQ / (4,500·A) [kg/m²]":"화재하중은 가연물 발열량의 합을 목재 4,500 kcal/kg과 바닥면적의 곱으로 나눈 값입니다.","q″ = h(T화염 − T벽) [W/m²]":"뉴턴 냉각법칙에서 대류 열유속은 열전달계수에 화염과 벽의 온도차를 곱한 값입니다.","q″ = k·ΔT / L [W/m²]":"푸리에 법칙에서 열유속은 열전도율과 온도차의 곱을 두께로 나눈 값입니다.","q″ = ε·σ·T⁴, σ = 5.67×10⁻⁸ W/m²·K⁴, T는 절대온도(K)":"복사 열유속은 방사율과 스테판-볼츠만 상수, 절대온도 네제곱의 곱입니다.","q″ = χr·Q / (4πR²)":"점열원 복사 열유속은 복사분율과 발열량의 곱을 구의 표면적 4πR²로 나눈 값입니다.","ΔP = 3,460·(1/T0 − 1/Ti)·h [Pa], T는 K(273+℃), h는 중성대로부터의 높이":"굴뚝효과의 압력차는 안팎 온도의 역수 차에 상수와 중성대로부터의 높이를 곱해 구합니다.","ΔT = 400 − 40 = 360℃, L = 0.03 m, 정답 1,200 W/m²에서 역산한 k = 0.1 W/m·K → 0.1×360/0.03 = 1,200 W/m²":"온도차 360℃, 두께 0.03 m로 열유속 1,200 W/m²가 되도록 역산한 열전도율이 0.1 W/m·K입니다.","ΔT = Q·L / (k·A) = 300×0.03 / (0.3×1) = 30℃":"전도 온도차는 열량에 두께를 곱해 열전도율과 면적의 곱으로 나눈 값이며 이 예는 30℃입니다.","① 가연물별 G×H 합산(kcal) ② 4,500 × 바닥면적으로 나눔":"가연물별로 양과 발열량을 곱해 합한 뒤 4,500에 바닥면적을 곱한 값으로 나눕니다.","가스가 축적된 상태에 신선한 공기가 갑자기 유입되어 급격히 연소하는 현상":"쌓인 가스에 신선한 공기가 갑자기 들어오면 급격히 연소하는 현상이 백드래프트입니다.","가스분출 화염은 사출방향으로 작용한다, 화염 높이는 사출속도와 관계가 있다":"가스분출 화염은 분출 방향으로 뻗고 화염 높이는 분출속도와 관계가 있습니다.","가스와 공기가 확산으로 섞이며 연소":"확산연소는 가스와 공기가 서로 퍼져 섞이면서 타는 방식입니다.","가스폭발, 분해폭발, 분진폭발, 분무폭발, 증기운폭발":"가스폭발, 분해폭발, 분진폭발, 분무폭발, 증기운폭발은 모두 기체 상태에서 일어나는 기상폭발의 종류입니다.","가스폭발은 기상폭발이다, 수증기폭발은 응상폭발이다":"가스폭발은 기체 상태에서 일어나는 기상폭발이고 수증기폭발은 액체에서 일어나는 응상폭발입니다.","가시거리 0.2~0.5 m, 화재 최성기 정도":"가시거리 0.2~0.5 m로 화재 최성기 수준의 연기입니다.","가시거리 1~2 m, 앞이 거의 보이지 않는 정도":"가시거리가 1~2 m로 줄어 눈앞조차 분간하기 어려운 연기 농도입니다.","가시거리 20~30 m, 연기감지기가 작동할 정도":"가시거리가 20~30 m이며 연기감지기가 작동할 정도의 연기 농도입니다.","가시거리 약 3 m, 어두침침한 것을 느끼는 정도":"가시거리가 약 3 m로 어두침침하다고 느끼는 정도입니다.","가시거리 약 5 m, 건물 내부에 익숙한 사람이 피난에 지장을 느끼는 정도":"가시거리가 약 5 m이며 건물에 익숙한 사람도 피난에 지장을 느끼는 농도입니다.","가연물, 산소공급원, 점화원, 연쇄반응":"연소가 일어나려면 가연물, 산소공급원, 점화원에 더해 연쇄반응까지 갖춰져야 합니다.","가연물의 양, 유동상태, 방출속도 등":"연소범위는 가연물의 양, 유동상태, 방출속도 같은 조건에도 영향을 받습니다.","가연물이 점화원과 접촉했을 때 연소가 시작되는 최저온도":"인화점은 점화원을 가까이 댔을 때 불이 붙는 가장 낮은 온도입니다.","가연성 가스와 공기를 미리 혼합해 연소(분젠버너, 가정용 가스기기 연소, 가스폭발)":"예혼합연소는 가스와 공기를 미리 섞어 태우는 방식으로 분젠버너와 가스폭발이 해당합니다.","가연성 고체의 미분이 공기 중에 부유하다 착화원 에너지를 받아 폭발":"분진폭발은 가연성 고체 가루가 공기 중에 떠 있다가 착화원 에너지를 받아 터지는 폭발입니다.","가장 멀리 위치한 두 직통계단 출입구 간 직선거리는 건축물 평면 최대 대각선 거리의 1/2 이상(스프링클러 등 설치 시 1/3 이상)":"가장 먼 두 직통계단 출입구는 건물 평면 최대 대각선 거리의 1/2 이상 떨어뜨리고 스프링클러가 있으면 1/3 이상입니다.","각 직통계단 간에는 각각 거실과 연결된 복도 등 통로를 설치":"직통계단마다 거실과 이어지는 복도 등 통로를 각각 설치해야 합니다.","감광계수법: m⁻¹ (Cs = (1/L)·ln(I0/I))":"감광계수는 빛이 연기를 지나며 줄어드는 정도로 연기 농도를 나타내며 단위는 m⁻¹입니다.","감광계수와 가시거리는 반비례 관계":"감광계수가 커질수록 가시거리는 짧아지므로 둘은 반비례합니다.","거실 바닥면적 50 m² 이상인 지하층에는 직통계단 외에 피난층 또는 지상으로 통하는 비상탈출구 및 환기통 설치, 제8조제2항 기준의 직통계단이 2개소 이상이면 예외":"거실 바닥면적 50 m² 이상인 지하층은 직통계단 외에 비상탈출구와 환기통을 두되 직통계단이 2개소 이상이면 예외입니다.","거실 바닥면적 합계 1,000 m² 이상: 환기설비, 바닥면적 300 m² 이상: 급수전 1개소 이상":"지하층 거실이 합계 1,000 m² 이상이면 환기설비가 필요하고 300 m² 이상이면 급수전도 한 곳 이상 필요합니다.","거주자의 피난경로와 소방대원의 진압경로 확보":"제연의 주된 목적은 거주자의 피난경로와 소방대원의 진압경로를 확보하는 것입니다.","건물 내부 온도가 외부보다 높을 때 발생":"굴뚝효과는 건물 내부 온도가 바깥보다 높을 때 나타나는 공기의 상승 흐름입니다.","건물 높이가 높을수록 커진다, 저층보다 고층건축물에서 효과가 크다":"건물이 높을수록 굴뚝효과가 커서 저층보다 고층건축물에서 더 뚜렷합니다.","건물의 30% 이상 70% 미만이 소실된 화재":"소실 정도가 30%에서 70% 사이이면 반소화재로 분류합니다.","건물의 70% 이상(입체면적 비율)이 소실되었거나, 그 미만이라도 잔존부분을 보수해도 재사용이 불가능한 화재":"전소화재는 건물의 70% 이상이 타 없어졌거나 그보다 적어도 보수해서 재사용할 수 없는 화재입니다.","건축물 내부에서 계단실로 통하는 출입구: 유효너비 0.9m 이상, 피난방향으로 열 수 있는 60분+ 방화문 또는 60분 방화문(언제나 닫힌 상태 유지 또는 연기·불꽃 감지로 자동으로 닫힘)":"계단실 출입구는 유효너비 0.9m 이상이며 피난방향으로 열리고 자동 폐쇄되는 60분+ 또는 60분 방화문입니다.","건축물 내부에서 계단으로 통하는 출입구에는 60분+ 방화문 또는 60분 방화문":"옥외 계단으로 나가는 건물 쪽 문은 60분+ 또는 60분 방화문이어야 합니다.","건축물 내부에서 노대·부속실로 통하는 출입구: 60분+ 또는 60분 방화문, 노대·부속실에서 계단실로 통하는 출입구: 60분+, 60분 또는 30분 방화문":"건물 내부에서 노대·부속실로 가는 출입구는 60분+나 60분 방화문, 계단실로 가는 출입구는 30분 방화문도 가능합니다.","건축물 내부에서 피난안전구역으로 통하는 계단은 특별피난계단의 구조":"피난안전구역으로 이어지는 건물 내부 계단은 특별피난계단과 같은 구조를 갖춥니다.","건축물 내부와 계단실은 노대를 통하거나, 외부를 향해 열 수 있는 면적 1 m² 이상의 창문(바닥에서 1m 이상 높이), 또는 배연설비가 있는 면적 3 m² 이상의 부속실을 통하여 연결":"특별피난계단은 건물 내부와 계단실을 노대, 면적 1 m² 이상 창문, 또는 배연설비 있는 3 m² 이상 부속실로 잇습니다.","건축물 내부와 접하는 계단실 창문등(출입구 제외)은 망입유리 붙박이창으로서 각 1 m² 이하":"건물 내부와 접한 계단실 창문은 출입구를 뺀 나머지가 망입유리 붙박이창으로 각 1 m² 이하여야 합니다.","건축물 일부의 주요구조부를 내화구조로 한 경우 그 부분과 그 밖의 부분을 방화구획으로 구획":"건축물 일부만 내화구조로 지었을 때는 그 부분과 나머지 부분을 방화구획으로 나눕니다.","경제계획은 방재계획 설정요소가 아니다":"경제계획은 방재계획을 세울 때 정하는 요소에 들지 않습니다.","계단 대체 경사로: 경사도 1:8을 넘지 않을 것, 표면은 거친 면 또는 미끄러지지 않는 재료":"계단 대신 쓰는 경사로는 경사도가 1:8을 넘지 않고 표면이 거칠거나 미끄럽지 않아야 합니다.","계단실·노대·부속실은 창문등을 제외하고 내화구조의 벽으로 각각 구획":"특별피난계단은 계단실과 노대, 부속실을 서로 갈라 각각 내화구조 벽 안에 둡니다.","계단실·노대·부속실의 바깥쪽에 접하는 창문등(망입유리 붙박이창 각 1 m² 이하 제외)은 그 밖의 부분 창문등으로부터 2m 이상 거리":"계단실·노대·부속실의 바깥쪽 창문 등은 다른 부분 창문에서 2m 이상 떨어뜨리고 망입유리 붙박이창 각 1 m² 이하는 제외합니다.","계단실 및 부속실의 실내에 접하는 부분의 마감과 바탕은 불연재료":"계단실과 부속실의 실내 쪽 마감과 바탕은 불연재료로 해야 합니다.","계단실 바깥쪽과 접하는 창문등(망입유리 붙박이창으로서 각 1 m² 이하인 것 제외)은 건축물 다른 부분의 창문등으로부터 2m 이상 거리를 둘 것":"계단실 바깥쪽 창문 등은 망입유리 붙박이창 1 m² 이하를 빼고 다른 부분 창문에서 2m 이상 띄웁니다.","계단실·승강로·복도·화장실은 밀도 산정에서 제외, 취사장·조리장은 9.30":"계단실, 승강로, 복도, 화장실은 밀도 산정에서 빼고 취사장·조리장은 9.30을 적용합니다.","계단실에는 노대 또는 부속실에 접하는 부분 외에는 건축물 내부와 접하는 창문등을 설치하지 않는다":"계단실에는 노대나 부속실에 접한 부분 외에 건물 내부와 접하는 창문 등을 두지 않습니다.","계단실에는 예비전원에 의한 조명설비":"계단실에는 정전에도 켜지도록 예비전원으로 작동하는 조명설비를 둡니다.","계단실은 창문등을 제외하고 건축물의 다른 부분과 내화구조의 벽으로 구획":"계단실 벽은 창문 등을 제외하면 내화구조여야 하며 이 벽이 계단실을 건물 나머지와 분리합니다.","계단실의 노대 또는 부속실에 접하는 창문등(출입구 제외)은 망입유리 붙박이창으로서 각 1 m² 이하":"노대나 부속실에 접한 계단실 창문은 출입구를 뺀 나머지가 망입유리 붙박이창으로 각 1 m² 이하여야 합니다.","계단실의 실내에 접하는 부분(바닥·반자 등 모든 부분)의 마감과 바탕은 불연재료":"계단실 안쪽의 바닥과 반자 등 모든 마감과 바탕은 불연재료로 해야 합니다.","계단으로 통하는 복도 등 피난로는 단순하게 설계":"계단으로 이어지는 복도 같은 피난로는 단순하게 설계합니다.","계단은 그 계단으로 통하는 출입구 외의 창문등(망입유리 붙박이창 각 1 m² 이하 제외)으로부터 2m 이상 거리를 두고 설치":"옥외 피난계단은 출입구 외의 창문 등과 2m 이상 떨어뜨려 설치하며 망입유리 붙박이창 각 1 m² 이하는 제외합니다.","계단은 내화구조로 하고 지상까지 직접 연결":"옥외 계단은 내화구조로 만들고 중간에 끊김 없이 지상까지 연결합니다.","계단은 내화구조로 하고 피난층 또는 지상까지 직접 연결":"계단은 내화구조로 만들어 피난층이나 지상까지 곧바로 이어지게 합니다.","계단은 내화구조로 하되 피난층 또는 지상까지 직접 연결":"특별피난계단도 내화구조로 만들어 피난층이나 지상까지 직접 연결합니다.","계단은 보행거리를 기준으로 균등 배치":"계단은 보행거리를 기준으로 고르게 배치합니다.","계단의 유효너비 0.9m 이상":"옥외 피난계단의 유효너비는 0.9m 이상이어야 합니다.","계단의 유효 높이 2.1m 이상":"계단의 유효 높이는 2.1m 이상이어야 합니다.","계단이나 에스컬레이터로부터 2m 이상 거리":"회전문은 계단이나 에스컬레이터에서 2m 이상 떨어뜨려 설치합니다.","고강도 콘크리트(설계기준강도 50MPa 이상)를 사용하는 경우 국토교통부장관 고시 내화성능 관리기준에 적합해야 한다":"설계기준강도 50MPa 이상 고강도 콘크리트 기둥은 국토교통부장관 고시의 내화성능 관리기준에 맞아야 합니다.","고강도 콘크리트를 사용하는 경우 고시 내화성능 관리기준에 적합해야 한다":"보와 지붕틀에 고강도 콘크리트를 쓰면 고시된 내화성능 관리기준에 적합해야 합니다.","고온·고압 증기로 양생된 경량기포 콘크리트패널 또는 경량기포 콘크리트블록조로서 두께 10cm 이상":"증기 양생한 경량기포 콘크리트패널이나 블록조로 만든 벽은 두께 10cm 이상이면 내화구조입니다.","고온 유류 표면에 물을 주입하면 물이 급격히 증발해 유류가 비산·넘침":"슬롭오버는 뜨거운 유류 표면에 물을 넣으면 물이 급격히 증발해 유류가 튀고 넘치는 현상입니다.","고체가 녹아 증발한 증기가 연소":"증발연소는 고체가 녹아 증발한 증기가 타는 방식입니다.","골구를 철골조로 하고 양면을 두께 3cm 이상의 철망모르타르 또는 두께 4cm 이상의 콘크리트블록·벽돌·석재로 덮은 것":"철골 골구 비내력벽은 양면을 철망모르타르 3cm 이상이나 블록·벽돌·석재 4cm 이상으로 덮습니다.","골구를 철골조로 하고 양면을 두께 4cm 이상의 철망모르타르 또는 두께 5cm 이상의 콘크리트블록·벽돌·석재로 덮은 것":"철골 골구에 양면을 철망모르타르 4cm 이상이나 블록·벽돌·석재 5cm 이상으로 덮으면 내화구조 벽입니다.","공기가 부족하거나 환기량이 적을수록 CO 생성이 증가한다":"공기가 부족하거나 환기가 적으면 불완전연소가 늘어 일산화탄소가 더 생깁니다.","공기 밀도가 감소하면 부력이 생겨 따뜻한 공기는 상승한다":"공기 밀도가 줄면 부력이 생겨 따뜻한 공기가 위로 올라갑니다.","공기비(m) = 실제공기량 ÷ 이론공기량":"공기비는 실제공기량을 이론공기량으로 나눈 값입니다.","공기 유입이 불충분해 발염연소가 억제되고 훈소 상태가 되기 쉽다":"내화건축물은 공기 유입이 부족해 발염연소가 억제되고 훈소 상태가 되기 쉽습니다.","공기 중 산소가 부족해도 연소가 진행된다":"자기연소는 물질 안의 산소로 타기 때문에 공기 중 산소가 부족해도 진행됩니다.","공동주택(층당 4세대 이하 제외)·오피스텔: 해당 용도 거실 바닥면적 합계 300 m² 이상":"공동주택과 오피스텔은 해당 용도 거실 바닥면적 합계가 300 m² 이상이면 직통계단을 여러 개소 둡니다.","공연장 개별 관람실(300 m² 이상): 출구 2개소 이상, 각 출구 유효너비 1.5m 이상, 출구 유효너비 합계는 바닥면적 100 m²마다 0.6m 비율 이상":"300 m² 이상 공연장 관람실은 출구 2개소 이상, 각 유효너비 1.5m 이상, 합계는 100 m²마다 0.6m 비율 이상입니다.","공연장·집회장·관람장·판매시설 등 계단: 유효너비 120cm 이상":"사람이 많이 모이는 공연장, 집회장, 관람장, 판매시설의 계단 폭은 120cm 이상입니다.","과잉공기량 = 실제공기량 − 이론공기량":"과잉공기량은 실제공기량에서 이론공기량을 뺀 만큼입니다.","관람실·집회실에서 바깥쪽으로의 출구 문은 안여닫이로 해서는 안 된다":"관람실·집회실에서 바깥쪽으로 나가는 출구 문은 안여닫이로 하면 안 됩니다.","관리사무소 또는 방재센터 등과 긴급연락이 가능한 경보 및 통신시설":"관리사무소나 방재센터와 긴급 연락이 되는 경보 및 통신시설을 갖춥니다.","구획실 가스발생량의 변화 추이는 환기계수 A√H에 큰 영향을 받는다":"구획실의 가스 발생량 변화는 환기계수 값에 크게 좌우됩니다.","구획실 성장기는 대류, 최성기는 복사가 지배적인 열전달":"구획실에서 성장기에는 대류가, 최성기에는 복사가 열전달을 지배합니다.","굴뚝효과, 온도 상승에 의한 공기의 팽창, 건물 내 기류에 의한 강제이동, 부력":"연기 이동 요소는 굴뚝효과, 온도 상승에 따른 공기 팽창, 건물 내 기류에 의한 강제 이동, 부력입니다.","그 밖의 건축물: 위층부터 최상층까지 거실 바닥면적 합계 200 m² 이상(지상층) 또는 지하층 거실 바닥면적 합계 100 m² 이상이면 유효너비 120cm 이상":"그 밖의 건축물은 위층 거실 바닥면적 합계가 지상 200 m², 지하 100 m² 이상이면 계단 유효너비 120cm 이상입니다.","그 밖의 용도 건축물: 유효 너비 1.5m 이상":"그 밖의 용도 건축물의 대지 안 통로는 유효 너비 1.5m 이상입니다.","그 자체는 독성가스가 아니나 호흡을 촉진해 다른 유독가스·수증기 흡입량을 늘린다":"이산화탄소는 독성이 없어도 호흡을 빠르게 해 다른 유독가스나 수증기를 더 마시게 합니다.","금속분, 곡물가루, 석탄가루 등 가연성 고체의 미분":"분진폭발은 금속분, 곡물가루, 석탄가루처럼 가연성 고체의 미세한 가루에서 일어납니다.","금속에 대한 부식성이 강하다":"염화수소는 금속을 심하게 부식시키는 성질이 있습니다.","급배기 기계제연방식은 부력이 아니라 기계력을 이용한다":"급배기 기계제연방식은 팬 같은 기계력으로 연기를 처리하므로 부력 방식이 아닙니다.","급수관·배전관·전선 등이 방화구획을 관통하는 부분, 벽과 벽·벽과 바닥·바닥과 바닥 사이 접합부, 방화구획과 외벽 사이 접합부, 그 밖의 틈은 별표 1 내화시간 이상 견디는 내화채움성능이 인정된 구조로 메운다":"배관과 전선이 방화구획을 뚫는 곳과 접합부의 틈은 별표 1 내화시간 이상 견디는 내화채움성능 구조로 메웁니다.","기체 연소 방식이며 고체 연소방식이 아니다":"예혼합연소는 기체 연소의 방식이지 고체의 연소방식이 아닙니다.","기타의 계단 유효너비 60cm 이상":"기타 계단의 유효너비는 60cm 이상이면 됩니다.","난류는 화염 전파속도를 증가시켜 폭발 위력을 키운다":"난류는 화염 전파속도를 키워 분진폭발 위력을 높입니다.","난연재료: 불에 잘 타지 아니하는 성능을 가진 재료":"난연재료는 불에 잘 타지 않는 성능을 가진 재료입니다.","내력벽, 기둥, 바닥, 보, 지붕틀 및 주계단":"주요구조부는 내력벽, 기둥, 바닥, 보, 지붕틀, 주계단입니다.","내부 벽면의 단열 성능이 우수할수록 도달 시간은 단축된다(열 손실이 적어 축열)":"벽 단열이 좋으면 열 손실이 적어 열이 쌓이므로 플래시오버에 이르는 시간이 줄어듭니다.","내외 온도차가 클수록 커지고, 온도가 같으면 발생하지 않는다":"안팎 온도차가 클수록 굴뚝효과가 세지고 온도가 같으면 생기지 않습니다.","내장재 열전도율이 낮을수록, 비열이 작을수록 실내온도가 빨리 올라 플래시오버가 빨라진다":"내장재의 열전도율과 비열이 낮으면 실내온도가 빨리 올라 플래시오버가 앞당겨집니다.","내화구조로 된 바닥 및 벽, 60분+ 방화문·60분 방화문 또는 자동방화셔터":"방화구획은 내화구조 바닥과 벽, 60분+ 방화문, 60분 방화문 또는 자동방화셔터로 나눕니다.","냉각소화, 질식소화, 제거소화(희석 포함)":"물리적 소화는 냉각, 질식, 제거(희석 포함) 세 방식으로 불을 끄는 방법입니다.","너비 3m를 넘는 계단: 중간에 3m 이내마다 난간(단높이 15cm 이하 + 단너비 30cm 이상이면 예외)":"폭이 3m보다 넓은 계단은 가운데에도 난간을 3m 이내 간격으로 세우며 단높이 15cm 이하, 단너비 30cm 이상이면 생략됩니다.","노대 및 부속실에는 계단실 외의 건축물 내부와 접하는 창문등(출입구 제외)을 설치하지 않는다":"노대와 부속실에는 계단실 외에 건물 내부와 접하는 창문 등을 달지 않습니다.","높은 증기밀도는 파이어볼 형성에 영향을 미치는 요인이 아니다":"증기 밀도가 높은 것은 파이어볼 형성에 영향을 주는 요인이 아닙니다.","높이 1m를 넘는 계단·계단참 양옆에 난간":"높이 1m를 넘는 계단과 계단참은 양옆에 난간을 설치합니다.","높이 3m를 넘는 계단: 3m 이내마다 유효너비 120cm 이상 계단참":"계단이 3m보다 높으면 3m 안에 한 번씩 폭 120cm 이상의 쉬는 자리인 계단참을 만듭니다.","다중주택·다가구주택, 정신과의원(입원실), 인터넷컴퓨터게임시설제공업소(300 m² 이상), 학원·독서실, 판매시설, 여객용 운수시설, 의료시설(입원실 없는 치과병원 제외), 교육연구시설 중 학원, 아동 관련 시설·노인복지시설·장애인 거주시설·장애인 의료재활시설, 유스호스텔, 숙박시설: 3층 이상 층의 해당 용도 거실 바닥면적 합계 200 m² 이상":"다가구주택, 학원, 판매시설, 숙박시설 등은 3층 이상 해당 용도 거실 바닥면적 합계 200 m² 이상이면 직통계단을 여러 개소 둡니다.","단독주택, 동·식물 관련 시설, 국방·군사시설(집회·체육·창고 용도) 건축물":"단독주택과 동·식물 관련 시설은 방화구획을 완화하며 국방·군사시설도 집회·체육·창고 용도이면 같습니다.","단독주택: 유효 너비 0.9m 이상":"단독주택의 대지 안 통로는 유효 너비 0.9m 이상이어야 합니다.","대량의 가연성 증기가 개방 공간에서 구름을 이루다 착화되어 폭발":"증기운폭발은 많은 양의 가연성 증기가 열린 공간에서 구름을 이루다 착화되어 터지는 폭발입니다.","대피공간 면제: 발코니 경계벽이 파괴하기 쉬운 경량구조, 경계벽에 피난구, 발코니 바닥에 하향식 피난구, 고시 대체시설":"발코니 경계벽이 경량구조이거나 피난구, 하향식 피난구, 고시 대체시설이 있으면 대피공간을 면제합니다.","덮개: 품질시험 결과 비차열 1시간 이상 내화성능, 유효 개구부 규격 직경 60cm 이상":"하향식 피난구 덮개는 비차열 1시간 이상 내화성능이 있어야 하고 유효 개구부 직경은 60cm 이상입니다.","덮개 개방 시 건축물관리시스템 등을 통한 경보음, 피난구에 예비전원 조명설비":"덮개를 열면 건축물관리시스템 등을 통해 경보음이 울리고 피난구에는 예비전원 조명설비를 둡니다.","마찰열, 압축열, 마찰스파크":"기계적 열원은 물체의 마찰이나 압축으로 생기는 마찰열, 압축열, 마찰스파크입니다.","망입유리는 지붕의 내화구조 기준이다, 계단의 내화구조가 아니다":"망입유리는 지붕의 내화구조 기준에 들고 계단의 내화구조 기준에는 들지 않습니다.","매층마다 구획, 다만 지하 1층에서 지상으로 직접 연결하는 경사로 부위는 제외":"매층마다 구획하며 지하 1층에서 지상으로 바로 이어지는 경사로 부분만 예외입니다.","멜라민수지는 질소 함유 수지로 HCN·NH3 등이 발생한다":"멜라민수지는 질소를 포함해 타면 HCN과 NH3 같은 가스가 나옵니다.","면적 = (피난안전구역 윗층 재실자 수 × 0.5) × 0.28 m²":"윗층 재실자 수에 0.5를 곱하고 다시 0.28 m²를 곱한 값이 피난안전구역 면적입니다.","목재, 석탄, 종이, 플라스틱":"분해연소의 예로 목재, 석탄, 종이, 플라스틱이 있습니다.","목재 표면 168 kW/m² (1 m² → 168 kW)":"목재 표면의 단위면적당 열방출률은 168 kW/m²라 1 m²이면 168 kW입니다.","무근콘크리트조·콘크리트블록조·벽돌조·석조":"계단은 무근콘크리트조, 콘크리트블록조, 벽돌조, 석조이면 내화구조입니다.","무근콘크리트조·콘크리트블록조·벽돌조·석조로서 두께 7cm 이상":"무근콘크리트조·블록조·벽돌조·석조 비내력벽은 두께 7cm 이상이면 됩니다.","무기과산화물, 프로판, 암모니아는 중합폭발 물질이 아니다":"무기과산화물과 프로판, 암모니아는 중합 반응열로 폭발하는 물질이 아니라서 목록에서 제외됩니다.","문은 피난방향으로 열리고 실내에서 항상 열 수 있는 구조, 내부·외부에 비상탈출구 표시":"비상탈출구 문은 피난방향으로 열리고 실내에서 늘 열 수 있어야 하며 안팎에 표시를 합니다.","문항에서 인화점이 가장 높은 것은 경유":"제시된 물질 중 인화점이 가장 높은 것은 경유입니다.","문화 및 집회시설(동·식물원 제외)·종교·운동·장례시설 거실로서 시선 및 활동공간 확보를 위해 불가피한 부분":"문화·집회·종교·운동·장례시설 거실 중 시선과 활동 공간 확보로 불가피한 부분은 방화구획이 완화됩니다.","문화·집회 고정좌석 없는 공간 0.45, 고정좌석 아닌 의자 1.29, 무대 1.40, 게임제공업 1.02":"고정좌석 없는 문화·집회 공간 0.45, 일반 의자 1.29, 무대 1.40, 게임제공업 1.02가 재실자 밀도입니다.","물분무, 미분무, 포, 이산화탄소, 할론, 할로겐화합물 및 불활성기체, 분말, 강화액, 고체에어로졸소화설비":"물분무등소화설비에는 물분무, 미분무, 포, 이산화탄소, 할론, 할로겐화합물, 분말, 강화액, 고체에어로졸설비가 들어갑니다.","물이 섞인 고점도 유류가 가열되어 거품이 넘침(화재가 아니어도 발생)":"프로스오버는 물이 섞인 점도 높은 유류가 가열되어 거품이 넘치는 현상으로 화재가 아니어도 생깁니다.","물이 흡수하는 열: 현열(비열 × 질량 × 온도차) + 증발잠열":"물이 흡수하는 열은 비열에 질량과 온도차를 곱한 현열에 증발잠열을 더한 값입니다.","물질 1kg이 기여하는 지구온난화 정도 ÷ CO2 1kg이 기여하는 정도":"GWP는 물질 1kg이 일으키는 지구온난화 정도를 CO2 1kg의 정도로 나눈 값입니다.","물질 1kg이 파괴하는 오존량 ÷ CFC-11 1kg이 파괴하는 오존량":"ODP는 물질 1kg이 파괴하는 오존량을 CFC-11 1kg의 파괴량으로 나눈 값입니다.","물질의 비열과 증발잠열을 이용":"냉각소화는 물이 열을 흡수하는 비열과 증발잠열을 이용해 온도를 낮추는 방식입니다.","밀도·비열·열전도율이 클수록(열관성 kρc가 클수록) 점화까지의 시간이 길어진다":"열관성이 큰 물질은 열이 안으로 퍼져 표면이 쉽게 달아오르지 않아 점화까지 시간이 깁니다.","밀폐 공간 화재에서 산소 부족으로 불꽃을 내지 못하고 열분해 가연성":"백드래프트는 밀폐 공간 화재에서 산소가 모자라 불꽃 없이 가연성 열분해 가스만 쌓인 상태에서 시작됩니다.","밀폐된 탱크가 가열되어 액체가 비등하며 압력이 상승해 폭발":"BLEVE는 밀폐 탱크가 가열되어 액체가 끓고 압력이 올라 터지는 폭발입니다.","밀폐 탱크가 가열되어 유류가 비등하고 압력이 상승해 폭발":"BLEVE는 밀폐 탱크가 가열되어 유류가 끓고 압력이 올라 폭발하는 현상입니다.","바닥면적 1,000 m² 이내마다, 스프링클러 등 자동식 소화설비 설치 시 3,000 m²":"바닥면적 1,000 m² 이내마다 구획하되 자동식 소화설비를 설치하면 3,000 m²까지 허용됩니다.","바닥면적 1,000 m² 이상인 층: 방화구획 각 부분마다 직통계단 1개소 이상, 피난계단 또는 특별피난계단 구조":"1,000 m² 이상 층은 방화구획된 부분마다 직통계단을 한 곳 이상 두며 이를 피난계단 구조로 만듭니다.","바닥면적 1 m²당 1 m³/min 이상, 최소 배출량 5,000 m³/h 이상":"예상제연구역 배출량은 바닥면적 1 m²당 1 m³/min 이상이며 최소 5,000 m³/h 이상입니다.","바닥면적 200 m² 이내마다, 자동식 소화설비 설치 시 600 m²":"바닥면적 200 m² 이내마다 구획하되 자동식 소화설비를 설치하면 600 m²까지 허용됩니다.","바닥면적은 높이를 쓰지 않는다":"화재하중 계산에는 바닥면적만 쓰고 높이는 넣지 않습니다.","바닥면적 합계 500 m² 이상인 문화 및 집회시설·종교시설·의료시설·위락시설·장례시설: 유효 너비 3m 이상":"바닥면적 합계 500 m² 이상인 문화·집회·종교·의료·위락·장례시설의 대지 안 통로는 유효 너비 3m 이상입니다.","바닥에서 비상탈출구 아랫부분까지 높이 1.2m 이상이면 벽체에 발판 너비 20cm 이상의 사다리 설치":"비상탈출구 밑이 바닥에서 1.2m 이상 높으면 벽에 발판 너비 20cm 이상의 사다리를 붙여 오르내리게 합니다.","바로 아래층·위층에 고시 기준에 적합한 단열재 설치":"피난안전구역 바로 아래층과 위층에는 고시 기준에 맞는 단열재를 설치합니다.","반응열 = 생성물 생성열 합 − 반응물 생성열 합, CH4 + 2O2 → CO2 + 2H2O: Q = 94.1 + 2×57.8 − 17.9 = 191.8 kcal":"반응열은 생성물 생성열 합에서 반응물 생성열 합을 뺀 값이며 이 메테인 연소는 191.8 kcal입니다.","발열량 환산 예: C3H8 1 mol(44 g) = 530.6 kcal → 1 g = 530.6 / 44 = 12.06 kcal":"프로판 1 mol은 44 g에 530.6 kcal이므로 1 g당 12.06 kcal로 환산됩니다.","발화점이 낮을수록 점화까지의 시간이 짧아진다":"발화점이 낮은 물질일수록 점화까지 걸리는 시간이 짧아집니다.","방수량 (g/s) = 열방출속도 (kJ/s) ÷ 물 1 g이 흡수하는 열량 (kJ/g)":"방수량은 열방출속도를 물 1 g이 흡수하는 열량으로 나누어 초당 그램으로 구합니다.","방재계획의 주된 설정요소: 부지계획, 평면계획, 단면계획, 입면계획, 재료계획":"방재계획의 주된 설정요소는 부지, 평면, 단면, 입면, 재료 계획입니다.","방지대책: 가연물의 양 제한, 내장재의 불연화":"가연물 양을 제한하고 내장재를 불연화하면 플래시오버를 막는 데 도움이 됩니다.","방화구획된 계단실·복도·승강기의 승강장 및 승강로":"방화구획된 계단실, 복도, 승강기 승강장과 승강로는 다시 구획하지 않는 완화 대상입니다.","방화문 종류: 60분+ 방화문, 60분 방화문, 30분 방화문":"방화문은 60분+, 60분, 30분 세 종류로 나뉩니다.","배출량 45,000 m³/h 이상(기출 O 문장)":"예상제연구역이 통로이면 배출량이 45,000 m³/h 이상이라는 문장은 맞는 내용입니다.","벤치형 좌석 공간: 좌석길이 ÷ 45.5cm, 고정좌석 공간: 휠체어 공간 수 + 고정좌석 수":"벤치형 좌석은 좌석길이를 45.5cm로 나눈 수이고 고정좌석 공간은 휠체어 공간 수에 고정좌석 수를 더합니다.","벽돌조로서 두께 19cm 이상":"벽돌조 벽은 두께가 19cm 이상이면 내화구조입니다.","벽·반자 실내 마감을 불연재료로 한 경우: 500 m² (자동식 소화설비 설치 시 1,500 m²)":"벽과 반자의 실내 마감을 불연재료로 하면 500 m², 자동식 소화설비까지 설치하면 1,500 m²까지 허용됩니다.","별표 1의2 기준으로 산정한 면적 이상":"피난안전구역 면적은 별표 1의2 기준으로 산정한 면적 이상이어야 합니다.","복사분율 0.3을 곱한 7.64 kW/m²가 정답":"열 중 복사로 전해지는 비율인 0.3을 곱해 7.64 kW/m²가 되는 것이 정답입니다.","복사열은 절대온도의 4제곱에 비례하고 열전달 면적에 비례한다":"온도가 두 배가 되면 복사열이 열여섯 배가 되고 면적이 넓을수록 전달량도 커집니다.","복층형 공동주택의 세대별 층간 바닥 부분":"복층형 공동주택은 세대별 층간 바닥 부분의 방화구획이 완화됩니다.","분무연소는 액체 연료의 연소 방식이며 고체 연소방식이 아니다":"분무연소는 액체 연료에 쓰는 방식이며 고체 연소방식으로 분류하지 않습니다.","분자 내에 산소를 가진 물질":"자기연소는 분자 안에 산소를 가진 물질이 타는 방식입니다.","분출속도가 커서 불꽃이 노즐에서 떨어져 연소하는 현상":"리프팅은 분출속도가 커서 불꽃이 노즐에서 떠 연소하는 현상입니다.","분해 생성물의 양에 비례한다":"일산화탄소 농도는 분해로 생긴 생성물의 양에 비례합니다.","불꽃감지기 또는 연기감지기 중 하나와 열감지기를 설치할 것":"불꽃감지기나 연기감지기 중 하나와 열감지기를 함께 설치해야 합니다.","불꽃 없이(무염) 표면에서 천천히 타는 연소":"훈소는 불꽃 없이 표면에서 천천히 타는 무염연소입니다.","불꽃이나 연기를 감지한 경우 일부 폐쇄되는 구조":"자동방화셔터는 불꽃이나 연기를 감지하면 일부만 닫히는 구조입니다.","불연재료: 불에 타지 아니하는 성질을 가진 재료":"불연재료는 불에 타지 않는 성질을 가진 재료입니다.","불활성 가스를 첨가할수록 좁아진다":"질소 같은 불활성 가스를 넣으면 연소범위가 좁아집니다.","비상용 승강기는 피난안전구역에서 승하차할 수 있는 구조":"비상용 승강기는 피난안전구역에서 타고 내릴 수 있게 합니다.","사다리는 바로 아래층 바닥면으로부터 50cm 이하까지 내려오는 길이":"사다리는 아래층 바닥에서 50cm 이하 높이까지 닿도록 충분히 길게 합니다.","사이 기둥, 최하층 바닥, 작은 보, 차양, 옥외 계단 등 구조상 중요하지 아니한 부분":"구조상 중요하지 않은 사이 기둥, 최하층 바닥, 작은 보, 차양, 옥외 계단은 주요구조부에서 빠집니다.","산소, 오존(O3), 불소(F2), 염소(Cl2), 이산화질소(NO2) 등":"산소 외에 오존, 불소, 염소, 이산화질소도 연소를 돕는 조연성 가스로 산소 구실을 합니다.","산소가 제한되면 환기지배 상태가 된다":"불꽃 없는 훈소 상태에서 산소 공급이 막히면 환기에 지배받는 화재로 바뀝니다.","산소농도가 높을수록 넓어진다(주로 상한계 상승)":"산소농도가 높을수록 연소범위가 넓어지며 주로 상한계가 올라갑니다.","산소농도가 증가할수록 작아진다":"산소농도가 높을수록 적은 에너지로도 점화되어 최소점화에너지가 작아집니다.","산화프로필렌(특수인화물) < 휘발유·아세톤(제1석유류) < 경유(제2석유류)":"인화점은 산화프로필렌(특수인화물)이 가장 낮고 휘발유·아세톤(제1석유류), 경유(제2석유류) 순으로 높아집니다.","상부는 실외보다 압력이 높아 기체가 유출되고, 하부는 낮아 외부 공기가 유입된다":"중성대 위쪽은 실외보다 압력이 높아 기체가 나가고 아래쪽은 낮아 바깥 공기가 들어옵니다.","상층·하층간 피난구의 수평거리 15cm 이상":"상층과 하층의 피난구는 수평거리 15cm 이상 떨어뜨려 둡니다.","생성물: 메타인산(HPO3), 암모니아, 물":"이 분말이 열분해하면 메타인산, 암모니아, 물이 생깁니다.","석고판 위에 시멘트모르타르 또는 회반죽을 바른 것으로서 두께 합계 2.5cm 이상":"석고판 위에 시멘트모르타르나 회반죽을 발라 두께 합계가 2.5cm 이상이면 방화구조입니다.","셀룰로오스계 가연물 연소 시, 화재하중이 클수록 CO가 증가한다":"셀룰로오스계 가연물은 화재하중이 클수록 연소 중 일산화탄소가 늘어납니다.","소방관이 진입할 수 있는 창의 가운데에서 벽면 끝까지의 수평거리가 40m 이상이면 40m 이내마다 추가 설치":"진입창 가운데에서 벽 끝까지 40m 이상 떨어진 구간은 40m 이내마다 진입창을 더 둡니다.","소방차 진입로 또는 소방차 진입이 가능한 공터에 면할 것":"소방관 진입창은 소방차 진입로나 소방차가 들어올 수 있는 공터에 면해야 합니다.","소방청장이 정하는 소방 등 재난관리 설비":"소방청장이 따로 정한 소방과 재난관리용 설비를 이 구역에 더 둡니다.","손잡이: 최대지름 3.2cm 이상 3.8cm 이하 원형·타원형, 벽등에서 5cm 이상 떨어지고 계단에서 높이 85cm, 수평부분에서 바깥쪽으로 30cm 이상":"손잡이는 지름 3.2cm 이상 3.8cm 이하로 벽에서 5cm 이상 띄우고 계단 위 높이 85cm에 둡니다.","수분이 적을수록 발생 가능성이 높다":"분진은 수분이 적을수록 폭발할 가능성이 높아집니다.","수소 4~75 vol%, 메테인 5.0~15.0 vol%, 에테인 3.0~12.5 vol%, 프로판 2.1~9.5 vol%":"수소 4~75, 메테인 5.0~15.0 vol% 등 가스마다 연소범위의 하한과 상한이 다릅니다.","수율(y, g/g) × 질량연소유속(m″, g/m²·s) × 연소면적(A, m²)":"일산화탄소 생성속도는 수율과 질량연소유속, 연소면적을 곱해 구합니다.","수증기폭발, 증기폭발(액화가스의 증기폭발), 전선폭발, 혼합위험성 물질폭발, 고체 상전이 폭발":"응상폭발에는 수증기폭발, 증기폭발, 전선폭발, 혼합위험성 물질폭발, 고체 상전이 폭발이 있습니다.","숙박·공동주택 18.6, 업무·운수 9.30, 판매 지하층·1층 2.80·그 외 층 5.60·배송공간 27.9, 창고·자동차 관련 46.5, 공장 9.30·제조업 시설 18.6":"숙박·공동주택 18.6, 업무·운수 9.30, 판매 지하층·1층 2.80, 공장 9.30처럼 용도별 밀도가 다릅니다.","숯, 코크스, 금속 등 표면에서 산소와 반응":"표면연소는 숯, 코크스, 금속처럼 표면에서 산소와 직접 반응해 타는 방식입니다.","스모크타워 제연방식, 자연제연방식":"스모크타워 제연방식과 자연제연방식은 부력을 주로 이용해 연기를 내보냅니다.","스프링클러설비는 물분무등소화설비가 아니다, 포·할로겐화합물 및 불활성기체·미분무소화설비는 해당한다":"스프링클러설비는 물분무등소화설비에 들지 않고 포, 할로겐화합물 및 불활성기체, 미분무설비는 들어갑니다.","습도가 낮을수록 연소확대가 빠르다":"습도가 낮을수록 목재가 말라 연소 확대가 빨라집니다.","시멘트모르타르 위에 타일을 붙인 것으로서 두께 합계 2.5cm 이상":"시멘트모르타르 위에 타일을 붙여 두께 합계가 2.5cm 이상이면 방화구조입니다.","시안화수소(사이안화수소), 염화비닐 등":"시안화수소와 염화비닐은 중합 반응열로 폭발하는 중합폭발 물질입니다.","식수공급을 위한 급수전 1개소 이상, 예비전원에 의한 조명설비":"피난안전구역에는 식수용 급수전 1개소 이상과 예비전원 조명설비를 둡니다.","실내 천장 부근에 모인 열분해 가연성 기체가 착화되어 천장에 화염덩어리가 굴러다니는 현상":"천장 아래에 고인 열분해 가스에 불이 붙어 화염덩어리가 천장을 따라 구르는 것이 롤오버입니다.","실제공기량: 실제 연소에 사용된 공기량, 이론공기량보다 크다":"실제공기량은 실제로 쓴 공기량이라 완전연소를 위해 이론공기량보다 많습니다.","심벽에 흙으로 맞벽치기한 것":"심벽에 흙으로 맞벽치기한 것도 방화구조에 속합니다.","아래층에서는 바로 위층의 피난구를 열 수 없는 구조":"각 층 피난구를 위층에서만 열 수 있고 아래층에서는 위층 피난구를 열 수 없습니다.","아세틸렌, 산화에틸렌, 히드라진 등":"아세틸렌, 산화에틸렌, 히드라진은 스스로 분해하며 폭발하는 분해폭발 물질입니다.","아세틸렌 2.5~81 vol%, 에틸렌 2.7~36 vol%, 일산화탄소 12.5~74 vol%, 부탄 1.8~8.4 vol%":"아세틸렌은 2.5~81 vol%로 연소범위가 아주 넓고 부탄은 1.8~8.4 vol%로 좁습니다.","아세틸렌 약 31 > 수소 약 18 > 에틸렌 약 12 > 에테인 약 3, 위험도가 가장 높은 것은 아세틸렌":"위험도는 아세틸렌 약 31, 수소 약 18, 에틸렌 약 12, 에테인 약 3 순으로 아세틸렌이 가장 큽니다.","아파트 4층 이상 각 세대가 2개 이상 직통계단을 쓸 수 없으면 발코니에 대피공간 1개 이상 설치, 공동 설치 3 m² 이상, 세대별 2 m² 이상, 출입문은 60분+ 방화문":"아파트 4층 이상 세대가 직통계단 2개 이상을 쓸 수 없으면 발코니에 대피공간을 두며 공동은 3 m², 세대별은 2 m² 이상입니다.","압력이 높아지면 일반적으로 넓어진다(상한계 상승)":"압력이 높아지면 보통 연소범위가 넓어지며 상한계가 올라갑니다.","압력이 높을수록, 분자 충돌 횟수가 많을수록 반응속도는 증가한다":"압력이 높고 분자 충돌이 잦을수록 반응이 빨라집니다.","압력이 높을수록, 산소농도가 높을수록 낮아진다":"압력과 산소농도가 높아질수록 발화점은 내려갑니다.","압력이 높을수록, 점화에너지가 클수록, 관경이 가늘수록, 정상연소속도가 빠를수록":"압력이 높고 점화에너지가 크며 관이 가늘고 연소속도가 빠를수록 폭굉유도거리가 짧아집니다.","압축열은 기계적 열원, 유전발열은 전기적 열원이다, 화학적 열원이 아니다":"압축열은 기계적 열원이고 유전발열은 전기적 열원이므로 둘 다 화학적 열원에 넣지 않습니다.","액면에서 증발한 증기가 연소(휘발유, 알코올, 등유)":"액체의 증발연소는 액면에서 증발한 증기가 타는 방식으로 휘발유, 알코올, 등유가 해당합니다.","액체를 미립화해 연소(중유 버너)":"분무연소는 액체를 미세한 방울로 만들어 태우는 방식이며 중유 버너가 예입니다.","얇은 가연물이 두꺼운 가연물보다 빨리 점화된다":"얇은 가연물은 열을 빨리 받아 두꺼운 것보다 먼저 점화됩니다.","억제소화(부촉매소화), 연쇄반응 차단":"화학적 소화는 연쇄반응을 끊는 억제소화, 곧 부촉매소화입니다.","언제나 닫힌 상태를 유지하거나 화재로 인한 연기 또는 불꽃을 감지하여 자동으로 닫히는 구조, 불가피하면 온도 감지 방식 가능":"방화문은 항상 닫혀 있거나 연기·불꽃 감지로 자동으로 닫히는 구조여야 하며 불가피하면 온도 감지 방식도 됩니다.","역화현상은 연기 이동 요소가 아니다(가스 연소 현상)":"역화는 가스 연소에서 생기는 현상이라 연기 이동 요소가 아닙니다.","연결되는 특별피난계단은 피난안전구역을 거쳐서 상·하층으로 갈 수 있는 구조":"특별피난계단은 피난안전구역을 거쳐 위아래 층으로 갈 수 있는 구조여야 합니다.","연구원장이 인정한 내화구조 표준 또는 성능설계로 검증된 구조(국토교통부장관 승인 기준 적합)":"연구원장이 인정한 표준이나 성능설계로 검증되고 장관 승인 기준에 맞는 구조도 내화구조입니다.","연구원장이 제27조제1항에 따라 정한 인정기준에 따라 인정하는 것":"연구원장이 제27조제1항에 따라 정한 인정기준으로 인정한 구조도 내화구조에 해당합니다.","연기 등 연소생성물이 계단·복도 등을 따라 상층부로 이동하는 경향":"내화건축물에서는 연기 같은 연소생성물이 계단과 복도를 따라 위층으로 이동하는 경향이 있습니다.","연기 또는 불꽃 감지로 자동으로 닫히는 구조(주방 등 연기가 항상 발생하는 곳은 온도 감지 가능)":"댐퍼는 연기나 불꽃을 감지해 자동으로 닫혀야 하며 연기가 늘 나는 주방 등은 온도 감지도 가능합니다.","연기 및 독성가스 농도는 공급되는 공기량에 따라 변화한다":"연기와 독성가스 농도는 공급되는 공기량에 따라 달라집니다.","연기와 정전 등으로 시야가 흐려지거나 밀폐공간에서 공포 분위기가 조성될 때 개구부 등의 불빛, 어두운 곳에서 밝은 불빛을 따라 행동하는 본능":"지광본능은 연기나 정전으로 시야가 흐려지거나 공포 분위기일 때 밝은 불빛을 따라 움직이는 본능입니다.","연료지배형: 개구부가 충분해 가연물 양에 좌우":"연료지배형은 개구부가 충분해 가연물의 양이 연소를 좌우합니다.","연소가 일어나는 데 필요한 가연성 가스의 농도 범위, 하한계(LFL)~상한계(UFL)":"연소범위는 불이 붙을 수 있는 가연성 가스 농도 구간이며 하한계에서 상한계까지입니다.","연소속도가 분출속도보다 커서 불꽃이 버너 내부로 들어가는 현상":"역화는 연소속도가 분출속도보다 커서 불꽃이 버너 안쪽으로 들어오는 현상입니다.","연소속도가 빠를수록 작아진다":"연소속도가 빠른 가스일수록 점화에 필요한 에너지가 작습니다.","연소속도보다 가스 분출속도가 클 때, 주위 공기유동이 심해 불꽃이 노즐에서 떨어진 후 꺼지는 현상":"블로우오프는 분출속도가 연소속도보다 크거나 공기 흐름이 심해 불꽃이 노즐에서 떨어졌다가 꺼지는 현상입니다.","연소열, 분해열, 용해열, 자연발열(산화열·발효열·흡착열·중합열)":"화학적 열원에는 연소열, 분해열, 용해열과 산화열·발효열·흡착열·중합열 같은 자연발열이 있습니다.","연소하한계 × (완전연소에 필요한 O2 몰수)":"최소산소농도는 연소하한계에 완전연소에 필요한 산소 몰수를 곱해 구합니다.","연소 형태가 아니라 천장 부근 화염이 굴러다니는 화재 이상현상":"롤오버는 가스 연소 방식의 한 종류가 아니라 천장 쪽 화염 움직임을 가리키는 화재 현상입니다.","열방출속도가 낮고, 화염의 안정범위가 넓고 역화 위험이 없다":"확산연소는 열방출속도가 낮고 화염이 안정된 범위가 넓으며 역화 위험이 없습니다.","열방출속도가 높고 화염면 압력이 전파되면 충격파를 형성한다":"열방출속도가 높아 화염면 압력이 전파되면 충격파가 만들어집니다.","열분해로 생긴 가연성 가스가 연소":"분해연소는 열분해로 나온 가연성 가스가 타는 방식입니다.","열유속은 열전도율과 온도차에 비례하고 두께에 반비례":"물체가 두꺼울수록 열이 덜 전해지고 열전도율이 크거나 양쪽 온도차가 클수록 더 많이 전해집니다.","열을 감지한 경우 완전 폐쇄되는 구조":"열을 감지하면 자동방화셔터가 완전히 닫히는 구조입니다.","열이 외부로 방출되는 것보다 축적되는 것이 많다":"내화건축물은 열이 밖으로 나가는 양보다 안에 쌓이는 양이 많습니다.","염소는 조연성 가스로서 산소공급원 역할을 할 수 있다":"염소는 가연물과 반응해 연소를 돕기 때문에 산소공급원 역할이 가능합니다.","염소 함유 PVC 연소 때 다량 발생":"염화수소는 염소를 함유한 PVC가 탈 때 많이 나오는 가스입니다.","영향 요인: 화재실의 온도, 건축물 내·외의 온도차, 건축물의 높이":"굴뚝효과는 화재실 온도, 건물 안팎의 온도차, 건축물 높이에 영향을 받습니다.","예 2026-22: Q̇ = 5,000 kW, D = 2 m → 0.235×30.2 − 2.04 ≈ 5 m":"열방출률 5,000 kW와 지름 2 m를 식에 넣으면 화염 높이가 약 5 m입니다.","예 2026-25: 1/268 − 1/293 = 3.18×10⁻⁴, ×3,460 = 1.10 Pa/m, h = 30 m → 약 33 Pa":"역수 차 3.18×10⁻⁴에 3,460을 곱한 1.10 Pa/m에 높이 30 m를 곱해 약 33 Pa입니다.","예: 정전 대비 비상조명, 피난기구 설치, 자동장치 실패 대비 수동기동장치":"정전에 대비한 비상조명, 피난기구, 자동장치 실패에 대비한 수동기동장치가 페일 세이프의 예입니다.","예외(주요구조부가 내화구조 또는 불연재료): 5층 이상인 층의 바닥면적 합계 200 m² 이하이거나 5층 이상인 층의 바닥면적 200 m² 이내마다 방화구획이 되어 있는 경우":"주요구조부가 내화구조·불연재료이고 5층 이상 층 바닥면적 합계가 200 m² 이하이거나 200 m² 이내마다 방화구획되면 예외입니다.","오른손잡이는 오른발을 축으로 좌측으로 행동하는 본능":"좌회본능은 오른손잡이가 오른발을 축으로 왼쪽으로 움직이는 본능입니다.","옥상광장을 설치해야 하는 건축물은 옥상으로 통하도록 설치하고, 옥상 출입문은 피난방향으로 열리는 구조":"옥상광장을 둬야 하는 건축물은 계단이 옥상으로 통해야 하고 옥상 출입문은 피난방향으로 열려야 합니다.","온도, 산소농도, 촉매, 압력, 가연물 성질":"연소속도는 온도, 산소농도, 촉매, 압력, 가연물의 성질로 정해집니다.","온도가 높을수록, 활성화에너지가 작을수록 반응속도가 증가한다":"온도가 높고 활성화에너지가 작을수록 반응속도가 빨라집니다.","온도가 상승하면 작아진다(온도가 낮을수록 커진다)":"온도가 오르면 최소점화에너지가 작아져 불이 붙기 쉬워집니다.","요양병원·정신병원·노인요양시설·장애인 거주시설·장애인 의료재활시설의 피난층 외의 층: 각 층 방화구획된 대피공간, 거실에 접한 노대등, 계단 없이 지상으로 통하는 경사로 또는 인접 건축물 연결복도·연결통로 중 하나":"요양병원 등은 피난층 외 각 층에 방화구획된 대피공간, 노대, 경사로 또는 연결복도 중 하나를 둡니다.","운동시설 4.60, 도서관 서고 9.30·열람실 4.60, 학교·학원 교실 1.90, 보육 3.30, 의료 입원치료구역 22.3·수면구역 11.1, 교정 11.1":"운동시설 4.60, 학교·학원 교실 1.90, 보육 3.30, 의료 입원치료구역 22.3처럼 용도별 밀도가 정해집니다.","원시적 방법(사람의 본능·눈과 귀)을 전기적 장치 이용방법보다 우선한다":"사람의 본능과 눈·귀 같은 원시적 방법을 전기적 장치보다 앞세워 피난을 계획합니다.","위 용도 외 3층 이상의 층: 거실 바닥면적 합계 400 m² 이상":"위 용도 외의 3층 이상 층은 거실 바닥면적 합계가 400 m² 이상이면 직통계단을 여러 개소 둡니다.","윗층 재실자 수: 해당 피난안전구역과 다음 피난안전구역 사이의 용도별 바닥면적 ÷ 사용 형태별 재실자 밀도의 합계":"윗층 재실자 수는 용도별 바닥면적을 사용 형태별 재실자 밀도로 나눈 값의 합계입니다.","유류화재, 인화성 액체 등 기름 성분, 표시색 황색":"B급은 인화성 액체 등 기름 성분이 타는 유류화재이며 표시색은 황색입니다.","유리: 플로트판유리 6mm 이하, 강화유리·배강도유리 5mm 이하, 또는 이를 구성한 이중·삼중 유리(비산방지필름 두께 50μm 이하)":"유리는 플로트판유리 6mm 이하, 강화유리·배강도유리 5mm 이하이고 이중·삼중 구성이면 비산방지필름 50μm 이하입니다.","유지류 연소 때 발생(CH2CHCHO)":"아크롤레인은 기름 같은 유지류가 탈 때 발생하는 가스입니다.","유효너비 0.75m 이상, 유효높이 1.5m 이상":"비상탈출구의 유효너비는 0.75m 이상, 유효높이는 1.5m 이상입니다.","이론공기량: 이론산소량 ÷ 0.21(공기 중 산소 21 vol%)로 계산한 공기량":"이론공기량은 이론산소량을 공기 중 산소 비율 0.21로 나눠 구한 공기량입니다.","이론산소량: 가연물이 완전연소하는 데 필요한 최소 산소량":"이론산소량은 가연물을 완전연소시키는 데 최소로 필요한 산소량입니다.","인화점 < 연소점 < 발화점":"같은 물질이면 인화점이 가장 낮고 연소점이 그다음, 발화점이 가장 높습니다.","일반화재, 가연물 목재·종이 등, 표시색 백색":"A급은 목재와 종이 같은 가연물에서 나는 일반화재이며 표시색은 백색입니다.","일산화탄소(CO)·수소(H2)는 가연성 가스이며 산소공급원이 아니다":"일산화탄소와 수소는 스스로 타는 가연성 가스일 뿐 산소공급원이 되지 못합니다.","일정규모 이상의 계단실에는 유입되는 연기를 배출할 수 있는 제연설비를 설치":"일정 규모 이상의 계단실에는 들어오는 연기를 빼는 제연설비를 설치합니다.","입자가 비산해 접촉한 가연물이 국부적으로 심하게 탄화된다":"분진폭발 뒤에는 입자가 흩날려 닿은 가연물이 국부적으로 심하게 탄화됩니다.","입자가 작고 밀도가 작을수록 표면적이 커져 폭발이 잘 일어난다":"가루가 곱고 가벼울수록 공기와 닿는 표면이 넓어져 분진폭발이 쉽게 일어납니다.","입자표면에 열에너지가 주어져 표면온도 상승 → 열분해로 가연성 가스 방출 → 공기와 혼합 → 착화·폭발":"입자 표면이 가열되어 열분해 가스가 나오고 공기와 섞여 착화되며 폭발로 이어집니다.","자동판매기·휴지통 등 피난에 방해되는 시설물을 설치하지 않는다":"자동판매기와 휴지통처럼 피난에 방해되는 시설물을 복도에 두지 않습니다.","자동화 생산시설에 자동식 소화설비를 설치한 국토교통부령 공장: 75m(무인화 공장 100m) 이하, 국토교통부령 공장은 반도체·디스플레이 패널·이차전지 제조 공장":"자동화 생산시설에 자동식 소화설비를 둔 공장은 보행거리가 75m, 무인화 공장은 100m 이하입니다.","자동회전문은 충격이 가해지거나 위험한 위치에 사용자가 있으면 전자감지장치 등으로 정지하는 구조":"자동회전문은 충격이 가해지거나 사용자가 위험한 위치에 있으면 전자감지장치로 멈추는 구조입니다.","작은 보·사이 기둥·최하층 바닥은 해당하지 않는다":"작은 보, 사이 기둥, 최하층 바닥은 주요구조부에 해당하지 않습니다.","작은 지름 25cm 이상 + 철골을 두께 5cm 이상의 콘크리트로 덮은 것":"작은 지름 25cm 이상 기둥의 철골을 콘크리트 5cm 이상으로 덮은 것도 내화구조입니다.","작은 지름 25cm 이상 + 철골을 두께 6cm(경량골재 5cm) 이상의 철망모르타르 또는 두께 7cm 이상의 콘크리트블록·벽돌·석재로 덮은 것":"작은 지름 25cm 이상 기둥에 철골을 철망모르타르 6cm(경량골재 5cm) 이상 등으로 덮어도 내화구조입니다.","작은 지름이 25cm 이상인 것으로서 철근콘크리트조 또는 철골철근콘크리트조":"기둥은 작은 지름이 25cm 이상인 철근콘크리트조나 철골철근콘크리트조라야 내화구조입니다.","저장량이 내용적의 1/2 이하로 충전된 탱크가 화재로 증기압력이 상승해 유류를 분출하며 파열":"오일오버는 저장량이 내용적의 1/2 이하인 탱크에서 증기압이 올라 유류를 뿜으며 파열하는 현상입니다.","저항열, 유도열, 유전열(유전발열), 아크열, 정전기열, 낙뢰열":"전기적 열원에는 저항열, 유도열, 유전열, 아크열, 정전기열, 낙뢰열이 있습니다.","전동방식이나 수동방식으로 개폐할 수 있을 것":"자동방화셔터는 전동방식이나 수동방식으로 열고 닫을 수 있어야 합니다.","전소·반소에 해당하지 않는 화재(30% 미만)":"전소나 반소에 속하지 않고 소실이 30% 미만이면 부분소화재입니다.","점화에너지 차단은 질식소화의 효과가 아니다(질식 = 산소 차단)":"질식소화는 산소를 차단하는 것이고 점화에너지를 막는 것은 질식소화의 효과가 아닙니다.","점화원 없이 스스로 발화하는 최저온도":"발화점은 불꽃 없이도 스스로 불이 붙는 가장 낮은 온도입니다.","점화원에 의해 분출 유증기가 착화되면 탱크 위쪽에 공 모양의 화구 형성":"분출한 유증기에 점화원이 닿으면 탱크 위쪽에 공 모양의 화구가 만들어집니다.","점화원에 의해 분출 증기가 착화되면 공 모양 화구(파이어볼) 형성":"분출한 증기에 점화원이 닿아 착화되면 공 모양의 화구인 파이어볼이 생깁니다.","점화원을 제거해도 연소가 지속되는 최저온도":"연소점은 점화원을 치워도 불이 계속 타는 가장 낮은 온도입니다.","정전 시에도 피난방향을 명백히 확인할 수 있는 표시를 한다":"정전이 되어도 피난방향을 분명히 알 수 있는 표시를 해 둡니다.","제1인산암모늄(NH4H2PO4)":"인산염계 분말의 주성분은 제1인산암모늄입니다.","제2종 근린생활시설 중 공연장·종교집회장, 문화 및 집회시설(전시장·동식물원 제외), 종교시설, 위락시설 중 주점영업, 장례시설: 해당 용도 바닥면적 합계 200 m² 이상(공연장·종교집회장은 각 300 m²)":"공연장, 종교집회장, 주점영업, 장례시설 등은 용도 바닥면적 합계 200 m² 이상이면 직통계단을 2개소 이상 둡니다.","제연은 플래시오버 성장을 억제하는 효과가 있다":"제연으로 연기와 열을 빼면 플래시오버로 커지는 것을 억제하는 효과가 있습니다.","제조·가공·운반(보관 제외)에 필요한 고정식 대형 기기·설비 설치를 위해 불가피한 부분":"제조·가공·운반에 필요한 고정식 대형 설비를 놓기 위해 불가피한 부분은 구획이 완화됩니다.","주방화재, 주방에서 동·식물유를 취급하는 조리기구에서 일어나는 화재":"K급은 조리기구에서 동·식물유가 타는 주방화재입니다.","주요구조부가 내화구조 또는 불연재료로 된 건축물로서 연면적이 1천 m²를 넘는 것":"주요구조부가 내화구조나 불연재료인 건축물은 연면적이 1천 m²를 넘으면 방화구획 대상입니다.","주요구조부가 내화구조 또는 불연재료인 건축물은 50m 이하(층수 16층 이상 공동주택의 16층 이상인 층은 40m 이하)":"내화구조·불연재료 건축물은 보행거리가 50m 이하로 완화되고 16층 이상 공동주택의 16층 이상은 40m 이하입니다.","주요구조부가 내화구조 또는 불연재료인 주차장":"주요구조부가 내화구조나 불연재료인 주차장은 방화구획 완화 대상입니다.","주요 원인은 산소(공기) 유입이며 복사열이 아니다":"백드래프트의 주된 원인은 산소 유입이며 복사열이 아닙니다.","준불연재료: 불연재료에 준하는 성질을 가진 재료":"준불연재료는 불연재료에 가까운 성질을 가진 재료입니다.","준초고층 건축물: 전체 층수의 1/2에 해당하는 층으로부터 상하 5개층 이내에 1개소 이상(국토교통부령 직통계단 설치 시 예외)":"준초고층 건축물은 전체 층수의 1/2에 해당하는 층에서 상하 5개층 이내에 피난안전구역을 1개소 이상 둡니다.","중·고등학교 계단: 유효너비 150cm 이상, 단높이 18cm 이하, 단너비 26cm 이상":"중·고등학교 계단은 단높이가 18cm 이하로 초등학교보다 높게 허용되고 너비 기준은 같습니다.","중성대에서는 압력차가 없어 연기 흐름이 가장 약하다":"중성대 높이에서는 안과 밖의 압력이 같아 연기가 거의 움직이지 않습니다.","중성대 위치는 개구부의 위치·크기에 좌우된다":"중성대 위치는 개구부가 어디에 얼마나 크게 나 있는지에 따라 정해집니다.","중심축에서 문틀 사이 간격을 포함한 날개 끝까지 길이 140cm 이상":"중심축에서 날개 끝까지의 길이는 문틀 간격을 포함해 140cm 이상이어야 합니다.","중질유 탱크 화재 때 바닥의 물이 과열·비등해 유류가 탱크 밖으로 분출":"보일오버는 중질유 탱크 화재에서 바닥의 물이 과열되어 끓으며 유류를 밖으로 뿜어내는 현상입니다.","중탄산나트륨(탄산수소나트륨, NaHCO3)":"탄산수소나트륨이라고도 하는 중탄산나트륨이 주성분인 분말약제입니다.","증발열·비열이 작을수록 위험":"증발열과 비열이 작은 물질은 열을 덜 빼앗겨 쉽게 달아올라 화재 위험이 큽니다.","지붕틀은 주요구조부에 해당한다":"지붕틀도 건물 하중을 받치므로 주요구조부에 들어갑니다.","지하가·호텔·차고·극장·백화점 등은 용도별 구획 및 별도 경로의 피난로 설치":"지하가, 호텔, 차고, 극장, 백화점 등은 용도별로 구획하고 별도 경로의 피난로를 둡니다.","지하층: 거실 바닥면적 합계 200 m² 이상":"지하층은 거실 바닥면적 합계가 200 m² 이상이면 직통계단을 여러 개소 둡니다.","지하층에 설치하는 바닥면적 합계 300 m² 이상인 공연장·집회장·관람장·전시장은 위 50m 완화에서 제외":"공연장·집회장·관람장·전시장이 지하층에 있고 바닥면적 합계가 300 m² 이상이면 50m 완화를 받지 못합니다.","지하층이 하나의 용도로 사용되는 경우: 피난안전구역 면적 = (수용인원 × 0.1) × 0.28 m²":"지하층이 한 용도이면 수용인원에 0.1과 0.28 m²를 곱해 피난안전구역 면적을 구합니다.","직경 2 m → 3.14 m²":"풀 지름이 2 m이면 면적은 3.14 m²입니다.","진공에서 손실이 없고 공기 중에서도 거의 손실이 없다":"복사는 진공에서도 전해지고 공기 중에서도 손실이 거의 없습니다.","진입부분·피난통로에는 통행에 지장 있는 물건을 방치하거나 시설물을 설치하지 않는다":"진입부분과 피난통로에는 통행에 방해되는 물건을 두거나 시설물을 설치하지 않습니다.","질소 함유 물질(울, 실크, 나일론, 폴리우레탄)이 연소할 때 발생":"시안화수소는 울, 실크, 나일론, 폴리우레탄 같은 질소 함유 물질이 탈 때 나옵니다.","창문 가운데에 지름 20cm 이상의 역삼각형을 야간에도 알아볼 수 있도록 빛 반사 등으로 붉은색 표시":"창 한가운데에 20cm 이상 크기 붉은 역삼각형을 야간에도 보이게 반사재 등으로 표시합니다.","창문 유리 폭 90cm 이상, 높이 1m 이상, 실내 바닥에서 창 아랫부분까지 높이 80cm 이내(난간 설치 노대등은 120cm)":"진입창은 유리 폭 90cm 이상, 높이 1m 이상이어야 하고 창 아랫부분은 바닥에서 80cm 이내(난간 있는 노대는 120cm)입니다.","창문 한쪽 모서리에 타격지점을 지름 3cm 이상의 원형으로 표시":"유리를 깨는 위치를 알리도록 모서리 한 곳에 지름 3cm 이상 원을 표시합니다.","천장은 연기가 차는 것을 막기 위해 가능한 높게 하고 불연재를 사용":"천장은 연기가 차는 것을 막으려 가능한 높게 하고 불연재를 씁니다.","철골을 두께 6cm(경량골재 5cm) 이상의 철망모르타르 또는 두께 5cm 이상의 콘크리트로 덮은 것":"철골을 철망모르타르 6cm(경량골재 5cm) 이상이나 콘크리트 5cm 이상으로 덮은 보도 내화구조입니다.","철골조의 지붕틀(바닥에서 아랫부분까지 높이 4m 이상)로서 바로 아래에 반자가 없거나 불연재료 반자가 있는 것":"높이 4m 이상 철골조 지붕틀은 바로 아래에 반자가 없거나 불연재료 반자이면 내화구조로 봅니다.","철근콘크리트조 또는 철골철근콘크리트조":"보와 지붕틀은 철근콘크리트조나 철골철근콘크리트조이면 내화구조입니다.","철근콘크리트조 또는 철골철근콘크리트조로서 두께 10cm 이상":"벽의 내화구조 기준으로 철근콘크리트조 또는 철골철근콘크리트조는 두께 10cm 이상이어야 합니다.","철근콘크리트조 또는 철골철근콘크리트조로서 두께 7cm 이상":"외벽 중 비내력벽은 철근콘크리트조 등으로 두께 7cm 이상이면 내화구조입니다.","철망모르타르로서 바름두께 2cm 이상":"방화구조 중 철망모르타르는 바름두께가 2cm 이상이어야 합니다.","철재로 보강된 유리블록 또는 망입유리(두꺼운 판유리에 철망을 넣은 것)로 된 것":"철재로 보강한 유리블록이나 철망을 넣은 망입유리로 된 지붕도 내화구조입니다.","철재로 보강된 콘크리트블록조·벽돌조·석조":"지붕은 철재로 보강한 콘크리트블록조, 벽돌조, 석조이면 내화구조입니다.","철재로 보강된 콘크리트블록조·벽돌조·석조로서 철재에 덮은 블록등의 두께 4cm 이상":"철재로 보강한 블록조·벽돌조·석조 비내력벽은 철재를 덮은 두께가 4cm 이상이어야 합니다.","철재로 보강된 콘크리트블록조·벽돌조·석조로서 철재에 덮은 블록등의 두께 5cm 이상":"바닥은 철재로 보강한 블록조·벽돌조·석조로 철재를 덮은 두께가 5cm 이상이어야 합니다.","철재로 보강된 콘크리트블록조·벽돌조·석조로서 철재에 덮은 콘크리트블록등의 두께 5cm 이상":"철재로 보강한 블록조·벽돌조·석조 벽은 철재를 덮은 두께가 5cm 이상이어야 합니다.","철재의 양면을 두께 5cm 이상의 철망모르타르 또는 콘크리트로 덮은 것":"철재 양면을 철망모르타르나 콘크리트 5cm 이상으로 덮은 바닥도 내화구조입니다.","초고층 건축물(50층 이상 또는 200m 이상): 직통계단과 직접 연결되는 피난안전구역을 지상층으로부터 최대 30개 층마다 1개소 이상":"초고층 건축물은 직통계단과 연결된 피난안전구역을 지상층부터 최대 30개 층마다 1개소 이상 둡니다.","초기(발화) → 성장기 → 플래시오버 → 최성기 → 감쇠기":"구획실 화재는 초기, 성장기, 플래시오버, 최성기, 감쇠기 순으로 진행됩니다.","초등학교 계단: 유효너비 150cm 이상, 단높이 16cm 이하, 단너비 26cm 이상":"초등학교는 계단 폭을 150cm 이상으로 넓히고 단높이를 16cm 이하로 낮추며 단너비는 26cm 이상으로 합니다.","최고온도가 낮고 연소 지속시간이 길다":"내화건축물은 저온장기형이라 최고온도가 낮고 연소 지속시간이 깁니다.","최고온도가 높고 연소 지속시간이 짧다, 내화건축물보다 최성기 온도가 높다":"목조건축물은 고온단기형이라 최고온도가 높고 연소 지속시간이 짧으며 최성기 온도가 내화건축물보다 높습니다.","최상층 또는 피난층의 대규모 회의장·강당·스카이라운지·로비·피난안전구역 등 불가피한 부분":"최상층이나 피난층의 대규모 회의장, 강당, 스카이라운지, 로비 등 불가피한 부분도 완화됩니다.","최성기에 도달하는 시간이 빠르다, 플래시오버 도달 시간도 빠르다":"목조건축물은 최성기와 플래시오버에 이르는 시간이 모두 빠릅니다.","최초의 완만한 연소가 폭굉으로 발전하기까지의 거리":"폭굉유도거리는 처음의 느린 연소가 폭굉으로 바뀌기까지 걸리는 거리입니다.","축압식 소화기: 소화분말을 채운 용기에 이산화탄소 또는 질소가스로 축압":"축압식 소화기는 분말을 채운 용기에 이산화탄소나 질소가스를 미리 눌러 넣어 압력을 유지합니다.","출입구로부터 3m 이상 떨어진 곳에 설치":"비상탈출구는 출입구에서 3m 이상 떨어진 곳에 설치합니다.","출입구의 유효너비 0.9m 이상, 피난방향으로 열 수 있을 것":"출입구의 유효너비는 0.9m 이상이며 피난방향으로 열 수 있어야 합니다.","출입문·벽으로 장소 간 압력차를 만드는 것은 가압(차단) 방식":"출입문과 벽으로 장소 사이에 압력차를 만들어 연기를 막는 방식이 가압, 곧 차단 방식입니다.","출입에 지장이 없도록 일정한 방향으로 회전":"회전문은 출입에 지장이 없게 일정한 방향으로 돌게 합니다.","출화실에서 연기가 분출하는 정도":"불이 난 방에서 연기가 뿜어져 나오는 정도의 농도입니다.","충격파가 있고 전파속도가 음속보다 빠르다, 파면에서 온도·압력·밀도가 불연속적으로 급변":"폭굉은 충격파를 동반하고 음속보다 빠르게 전파하며 파면에서 온도·압력·밀도가 갑자기 변합니다.","충격파 에너지에 의한 화학반응으로 전파된다, 정상연소의 열전달 기구와 다르다":"폭굉은 충격파 에너지가 일으키는 화학반응으로 번지므로 정상연소의 열전달 방식과 다릅니다.","층 전체가 순식간에 화염에 휩싸이며 모든 공간으로 입체적으로 확대되는 현상":"플래시오버는 한 층 전체가 순식간에 화염에 휩싸이며 모든 공간으로 입체적으로 번지는 현상입니다.","판매시설 용도 층으로부터의 직통계단 중 1개소 이상은 특별피난계단":"판매시설 층에서 내려가는 직통계단 중 1개소 이상은 특별피난계단이어야 합니다.","평소 사용하는 문·통로를 사용하거나 자신이 왔던 길로 되돌아가려는 본능":"귀소본능은 평소 쓰던 문과 통로, 자신이 왔던 길로 되돌아가려는 본능입니다.","포스겐 < 염화수소 < 일산화탄소 < 이산화탄소":"허용농도가 낮을수록 독성이 강하므로 포스겐이 가장 독하고 이산화탄소가 가장 약합니다.","폭굉 속도는 통상 1,000~3,500 m/s":"폭굉의 속도는 보통 1,000에서 3,500 m/s 범위입니다.","폭발은 물적조건인 폭발범위와 발화온도 등의 에너지 조건을 충족해야 한다":"폭발이 일어나려면 폭발범위 같은 물적 조건과 발화온도 등의 에너지 조건이 모두 갖춰져야 합니다.","표준상태에서 기체 1 mol = 22.4 L, 계수비 = 몰비 = 부피비":"표준상태 기체 1 mol은 22.4 L이고 반응식 계수비가 곧 몰비이자 부피비입니다.","풀이 순서: ① 성분별 V/L 계산 ② 합산 ③ 100 ÷ 합":"성분마다 농도를 하한계로 나눠 모두 더한 뒤 100을 그 합으로 나누는 순서입니다.","풀이 순서: 반응식 완성 → 계수비로 필요 몰수 → × 22.4 L (또는 분자량으로 질량)":"반응식을 맞추고 계수비로 필요한 몰수를 구한 뒤 22.4 L를 곱하거나 분자량을 곱합니다.","플래시오버 이전에는 주로 CO2가 화재 성장에 비례해 증가한다":"플래시오버 전에는 화재가 커지는 정도에 비례해 주로 CO2가 늘어납니다.","플래시오버 이후 CO 농도는 연료지배형 단계보다 수배~수십배 증가할 수 있다":"플래시오버 뒤에는 CO 농도가 연료지배형 단계보다 수배에서 수십 배까지 늘 수 있습니다.","피난경로 한 방향이 사용할 수 없을 때 다른 방향이 사용되도록 2방향 피난로를 상시 확보":"페일 세이프는 한 피난로가 막혀도 다른 방향이 쓰이도록 2방향 피난로를 늘 확보하는 원칙입니다.","피난계단·특별피난계단은 돌음계단으로 해서는 안 된다":"피난계단과 특별피난계단은 돌음계단으로 만들 수 없습니다.","피난로의 안전구획(조닝, 피난 존)을 설정하고 최종 안전한 피난 장소 쪽으로 갈수록 각 존의 안전성을 높인다":"피난로를 안전구획으로 나누어 최종 안전 장소에 가까운 존일수록 안전성을 높입니다.","피난방향으로 열리는 출입문은 페일 세이프가 아니라 풀 프루프 성격이다":"피난방향으로 열리는 출입문은 사람의 실수를 막는 풀 프루프에 가깝고 페일 세이프가 아닙니다.","피난복도의 폭은 피난인원이 빠른 시간 내에 계단 등 안전한 피난처로 갈 수 있는 크기":"피난복도의 폭은 피난인원이 빠른 시간 안에 계단 같은 안전한 곳으로 갈 수 있는 크기여야 합니다.","피난설비는 고정시설이 원칙, 이동식 기구는 탈출에 늦은 소수에 대한 예외적 보조수단":"피난설비는 고정시설이 원칙이고 이동식 기구는 탈출이 늦은 소수를 위한 보조 수단입니다.","피난안전구역은 해당 건축물의 1개 층을 대피공간으로 하며, 건축설비 공간과 같은 층에 설치할 때는 내화구조로 구획":"피난안전구역은 한 개 층을 대피공간으로 쓰며 건축설비 공간과 같은 층이면 내화구조로 구획합니다.","피난이 가능한 60분+ 방화문 또는 60분 방화문으로부터 3m 이내에 별도로 설치, 복합 방화셔터는 예외":"자동방화셔터는 피난이 가능한 방화문에서 3m 이내에 별도로 설치하며 복합 방화셔터는 예외입니다.","피난층 외의 층에서 거실의 각 부분으로부터 직통계단에 이르는 보행거리 30m 이하":"피난층이 아닌 층의 거실에서 직통계단까지 걸어가는 거리는 30m를 넘으면 안 됩니다.","피난통로 유효너비 0.75m 이상, 실내에 접하는 부분의 마감과 바탕은 불연재료":"피난통로는 유효너비 0.75m 이상이고 실내 쪽 마감과 바탕은 불연재료여야 합니다.","필로티 내 통로 길이 2m 이상이면 자동차 진입억제용 말뚝 등 보호시설 또는 단차":"필로티 안 통로가 길이 2m 이상이면 자동차 진입을 막는 말뚝 등 보호시설이나 단차를 둡니다.","필로티 등(벽면적 1/2 이상이 공간)을 주차장으로 사용하는 부분은 건축물의 다른 부분과 구획":"벽면적 1/2 이상이 공간인 필로티 등을 주차장으로 쓰는 부분은 건축물의 다른 부분과 구획합니다.","한국건설기술연구원장이 고시 방법으로 품질을 시험한 결과 별표 1의 성능기준에 적합할 것":"한국건설기술연구원장이 고시한 방법으로 시험해 별표 1의 성능기준에 맞으면 내화구조로 인정합니다.","한국건설기술연구원장이 생산공장 품질관리 상태를 확인하고 품질시험 결과 비차열 1시간 이상의 내화성능을 확보하였음을 인정한 것":"자동방화셔터는 연구원장이 품질관리와 시험 결과로 비차열 1시간 이상의 내화성능을 인정한 것이어야 합니다.","한국산업표준에 따라 시험한 결과 방화 2급 이상에 해당하는 것":"한국산업표준 시험에서 방화 2급 이상으로 나온 것도 방화구조입니다.","합판 0.12 m² → 45 kW (375 kW/m² 적용)":"합판 0.12 m²에 375 kW/m²를 적용해 45 kW를 얻습니다.","헤모글로빈과 결합해 산소 운반 기능을 약화시킨다":"일산화탄소는 헤모글로빈과 결합해 혈액의 산소 운반을 방해합니다.","혼란 시 판단력 저하로 최초로 달리는 앞사람을 따르는 본능":"추종본능은 혼란 속에서 판단력이 떨어져 처음 달리는 앞사람을 따라가는 본능입니다.","혼합가스의 연소범위는 르샤틀리에 공식을 따른다":"가스를 섞은 경우의 연소범위는 르샤틀리에 공식으로 계산합니다.","화염 800℃, q″ = 3,200 W/m², 정답 벽온도 0℃ → h = 3,200/800 = 4 W/m²·K (역산)":"대류 열유속 3,200 W/m²를 화염 800℃와 벽 0℃의 차로 나누어 열전달계수 4를 역산합니다.","화염의 분출면적이 크고 복사열이 커서 접근하기 어렵다":"목조건축물은 화염 분출면적이 크고 복사열이 커서 가까이 가기 어렵습니다.","화염의 확산을 막을 수 있는 성능을 가진 구조로서 국토교통부령으로 정하는 기준에 적합한 구조":"방화구조는 화염이 번지는 것을 막는 성능의 구조로 국토교통부령 기준에 맞아야 합니다.","화염전파는 파동 형태로 전파하므로 연소파라 하고 그 파면을 화염면이라 한다":"화염은 파동처럼 퍼지므로 연소파라 부르고 그 앞면을 화염면이라 합니다.","화염전파속도 = 연소속도 + 연소가스 팽창으로 전방으로 이동하는 속도":"화염전파속도는 연소속도에 연소가스 팽창으로 앞쪽으로 밀려가는 속도를 더한 값입니다.","화염전파속도가 음속보다 느린 연소":"폭연은 불꽃이 퍼지는 속도가 소리의 속도보다 느린 연소를 말합니다.","화재는 무염착화 → 발염착화의 순으로 진행":"목조건축물 화재는 불꽃 없는 무염착화에서 불꽃이 있는 발염착화 순으로 진행합니다.","화재를 작은 범위로 한정하기 위한 유효한 피난구획으로 조닝화":"화재를 작은 범위에 가두기 위해 유효한 피난구획으로 조닝화합니다.","화재실 상부에 큰 개구부가 있으면 중성대는 올라간다":"큰 개구부가 화재실 위쪽에 열려 있으면 중성대의 높이가 위로 이동합니다.","화재실 온도가 높을수록 중성대는 낮아지고, 낮을수록 높아진다":"화재실 온도가 높으면 중성대가 낮아지고 온도가 낮으면 높아집니다.","화재에 견딜 수 있는 성능을 가진 구조로서 국토교통부령으로 정하는 기준에 적합한 구조":"내화구조는 화재에 견디는 성능을 갖춘 구조로 국토교통부령 기준에 맞아야 합니다.","화재 초기에는 서로 모이지만 화세가 확대되면 공포감이 증가해 발화지점 반대방향으로 이동하는, 위험으로부터 멀리하려는 본능":"퇴피본능은 화세가 커져 공포가 늘면 발화지점 반대쪽으로 위험에서 멀어지려는 본능입니다.","화재 최성기에는 공기를 유입시키는 기계제연이 효과적이지 않다":"공기를 불어 넣는 기계제연은 화재 최성기에는 효과적이지 않습니다.","화학양론적 조성 부근에서 가장 작다":"화학양론적 조성 부근에서 가스와 산소가 알맞게 섞여 최소점화에너지가 가장 작습니다.","확산화염 플룸은 부력과 사출 운동량(관성력)의 영향을 함께 받는다":"확산화염 플룸은 부력과 분출 운동량의 영향을 함께 받습니다.","환기·난방·냉방 풍도가 방화구획을 관통하면 관통부분 또는 근접부분에 댐퍼를 설치":"환기·난방·냉방 풍도가 방화구획을 관통하면 관통부나 그 가까이에 댐퍼를 설치합니다.","환기지배형: 개구부가 작아 공기 공급이 연소를 제한":"개구부가 좁으면 공기가 부족해 연소가 억제되는 화재를 환기지배형이라 합니다.","활성화에너지가 클수록 반응속도는 감소한다":"활성화에너지가 클수록 반응을 시작하기 어려워 반응속도가 느려집니다.","황, 나프탈렌, 파라핀(양초)":"증발연소를 하는 고체에는 황, 나프탈렌, 파라핀이 있고 양초가 그 예입니다.","황 함유 물질 연소 때 발생":"황화수소는 황을 함유한 물질이 연소할 때 생깁니다.","회전문과 문틀 사이 5cm 이상, 회전문과 바닥 사이 3cm 이하, 틈은 고무와 고무펠트의 조합체 등으로 손상 방지":"회전문과 문틀 사이는 5cm 이상, 바닥 사이는 3cm 이하로 하고 틈은 고무 등으로 손상을 막습니다.","회전속도는 분당회전수 8회를 넘지 않을 것":"회전문의 회전속도는 분당 8회를 넘지 않아야 합니다.","횡방향보다 종방향의 화재성장이 빠르다":"목조건축물은 옆으로보다 위로 번지는 종방향 화재성장이 빠릅니다.","휘발성이 크고 발화온도가 낮을수록 폭발이 잘 발생한다":"휘발성이 크고 발화온도가 낮은 분진일수록 폭발이 잘 일어납니다.","희석: 신선한 다량의 공기를 유입해 연기생성물을 위험수준 이하로 유지":"희석은 신선한 공기를 많이 넣어 연기생성물 농도를 위험 수준 아래로 유지하는 방식입니다."}});if(window.DIAGRAM&&DIAGRAM.tnFlush)DIAGRAM.tnFlush();
/*tnote-data-end*/
